INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('6bf3f0f5-9afe-591c-9eb6-2d81851eeaf1', 'c33cd566-89db-55cf-8c76-1a85c317bd86', 15, '<p>පහත දක්වා ඇති ප්‍රතික්‍රියා පටිපාටි වලින් කුමක්, 1,2-dibromopropane ($CH_3CH(Br)CH_2Br$) පිළියෙළ කිරීම සඳහා සුදුසු නොවන්නේ ද?</p>', '<p>පහත දක්වා ඇති ප්‍රතික්‍රියා පටිපාටි වලින් කුමක්, 1,2-dibromopropane ($CH_3CH(Br)CH_2Br$) පිළියෙළ කිරීම සඳහා සුදුසු නොවන්නේ ද?</p>', NULL, '4 වන ක්‍රමයේදී ප්‍රොපයින ($CH_3C \equiv CH$) වැඩිපුර $Br_2$ සමග ප්‍රතික්‍රියා කර 1,1,2,2-tetrabromopropane සාදයි. එය හයිඩ්‍රජනීකරණයට ($H_2/Pt$) භාජනය කිරීමෙන් 1,2-dibromopropane ලබා ගැනීම සාර්ථක ක්‍රමයක් නොවේ. අනෙකුත් සියලුම පටිපාටි මගින් ප්‍රොපීන් ($CH_3CH=CH_2$) හෝ ප්‍රොපේන්-1,2-ඩයෝල් නිපදවා එයින් පහසුවෙන් 1,2-dibromopropane සාදාගත හැක.', '4 වන ක්‍රමයේදී ප්‍රොපයින ($CH_3C \equiv CH$) වැඩිපුර $Br_2$ සමග ප්‍රතික්‍රියා කර 1,1,2,2-tetrabromopropane සාදයි. එය හයිඩ්‍රජනීකරණයට ($H_2/Pt$) භාජනය කිරීමෙන් 1,2-dibromopropane ලබා ගැනීම සාර්ථක ක්‍රමයක් නොවේ. අනෙකුත් සියලුම පටිපාටි මගින් ප්‍රොපීන් ($CH_3CH=CH_2$) හෝ ප්‍රොපේන්-1,2-ඩයෝල් නිපදවා එයින් පහසුවෙන් 1,2-dibromopropane සාදාගත හැක.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('3fd94cce-1f59-46f2-b44d-63831063ca81', '6bf3f0f5-9afe-591c-9eb6-2d81851eeaf1', '$CH_3CH(OH)CH_3 \xrightarrow{\text{සාන්ද්‍ර } H_2SO_4, \Delta} \dots \xrightarrow{Br_2}$', '$CH_3CH(OH)CH_3 \xrightarrow{\text{සාන්ද්‍ර } H_2SO_4, \Delta} \dots \xrightarrow{Br_2}$', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('5a227600-da59-4563-a22d-c0bc1702cf6d', '6bf3f0f5-9afe-591c-9eb6-2d81851eeaf1', '$CH_3CH(OH)COOH \xrightarrow{LiAlH_4 / \text{වියළි ඊතර්, } H^+/H_2O} \dots \xrightarrow{\text{වැඩිපුර } PBr_3}$', '$CH_3CH(OH)COOH \xrightarrow{LiAlH_4 / \text{වියළි ඊතර්, } H^+/H_2O} \dots \xrightarrow{\text{වැඩිපුර } PBr_3}$', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('f6070e3e-2ab5-45b8-9d36-201241752d1a', '6bf3f0f5-9afe-591c-9eb6-2d81851eeaf1', '$CH_3C \equiv CH \xrightarrow{H_2 / Pd-BaSO_4 \text{ හා ක්විනොලීන්}} \dots \xrightarrow{Br_2}$', '$CH_3C \equiv CH \xrightarrow{H_2 / Pd-BaSO_4 \text{ හා ක්විනොලීන්}} \dots \xrightarrow{Br_2}$', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('6e76bd0c-a217-4ec0-a1d3-5aabf7b2105a', '6bf3f0f5-9afe-591c-9eb6-2d81851eeaf1', '$CH_3C \equiv CH \xrightarrow{\text{වැඩිපුර } Br_2} \dots \xrightarrow{H_2 / Pt}$', '$CH_3C \equiv CH \xrightarrow{\text{වැඩිපුර } Br_2} \dots \xrightarrow{H_2 / Pt}$', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('1e36ce27-0c9e-42cc-8393-3cef2a173372', '6bf3f0f5-9afe-591c-9eb6-2d81851eeaf1', '$CH_3CH_2CH_2Br \xrightarrow{\text{මධ්‍යසාරීය } KOH, \Delta} \dots \xrightarrow{Br_2}$', '$CH_3CH_2CH_2Br \xrightarrow{\text{මධ්‍යසාරීය } KOH, \Delta} \dots \xrightarrow{Br_2}$', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('c2441601-e363-550b-9fc3-b4bd907d1e60', 'c33cd566-89db-55cf-8c76-1a85c317bd86', 16, '<p>$H_2(g) + I_2(g) \rightarrow 2HI(g)$ ප්‍රතික්‍රියාව වේගයෙන් සිදුවන සමතුලිත පියවරකින් පසුව සෙමින් සිදුවන මූලික ප්‍රතික්‍රියා පියවරක් හරහා සිදු වේ.<br>සෙමින් සිදුවන මූලික ප්‍රතික්‍රියා පියවර සඳහා වේග නියමය, $\text{ශීඝ්‍රතාවය} = k''[H_2(g)][I(g)]^2$ වේ. වේග නියතය $k''$ වේ.<br>$[H_2(g)]$ සහ $[I_2(g)]$ අනුසාරයෙන් සම්පුර්ණ ප්‍රතික්‍රියාවෙහි වේග නියමය පහත සඳහන් කුමක් මගින් ලබා දෙයි ද? ($k$ යනු සම්පුර්ණ ප්‍රතික්‍රියාවේ වේග නියතය වේ.)</p>', '<p>$H_2(g) + I_2(g) \rightarrow 2HI(g)$ ප්‍රතික්‍රියාව වේගයෙන් සිදුවන සමතුලිත පියවරකින් පසුව සෙමින් සිදුවන මූලික ප්‍රතික්‍රියා පියවරක් හරහා සිදු වේ.<br>සෙමින් සිදුවන මූලික ප්‍රතික්‍රියා පියවර සඳහා වේග නියමය, $\text{ශීඝ්‍රතාවය} = k''[H_2(g)][I(g)]^2$ වේ. වේග නියතය $k''$ වේ.<br>$[H_2(g)]$ සහ $[I_2(g)]$ අනුසාරයෙන් සම්පුර්ණ ප්‍රතික්‍රියාවෙහි වේග නියමය පහත සඳහන් කුමක් මගින් ලබා දෙයි ද? ($k$ යනු සම්පුර්ණ ප්‍රතික්‍රියාවේ වේග නියතය වේ.)</p>', NULL, 'වේගවත් සමතුලිත පියවර වන්නේ අයඩීන් වියෝජනය වීමයි: $I_2(g) \rightleftharpoons 2I(g)$.<br>මෙම පියවරේ සමතුලිතතා නියතය $K = \frac{[I]^2}{[I_2]} \implies [I]^2 = K[I_2]$ වේ.<br>ප්‍රතික්‍රියාවේ ශීඝ්‍රතාවය සෙමින් සිදුවන පියවර මත රඳා පවතී: $\text{Rate} = k''[H_2][I]^2$.<br>$[I]^2$ වෙනුවට $K[I_2]$ ආදේශ කළ විට, $\text{Rate} = k'' \times K \times [H_2][I_2]$ ලැබේ.<br>$k'' \times K$ යනු නව නියතයක් වන $k$ බැවින්, අවසාන වේග නියමය $= k[H_2][I_2]$ වේ.', 'වේගවත් සමතුලිත පියවර වන්නේ අයඩීන් වියෝජනය වීමයි: $I_2(g) \rightleftharpoons 2I(g)$.<br>මෙම පියවරේ සමතුලිතතා නියතය $K = \frac{[I]^2}{[I_2]} \implies [I]^2 = K[I_2]$ වේ.<br>ප්‍රතික්‍රියාවේ ශීඝ්‍රතාවය සෙමින් සිදුවන පියවර මත රඳා පවතී: $\text{Rate} = k''[H_2][I]^2$.<br>$[I]^2$ වෙනුවට $K[I_2]$ ආදේශ කළ විට, $\text{Rate} = k'' \times K \times [H_2][I_2]$ ලැබේ.<br>$k'' \times K$ යනු නව නියතයක් වන $k$ බැවින්, අවසාන වේග නියමය $= k[H_2][I_2]$ වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
