INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('1bb7eab5-57dd-531a-8015-6818a0c918d1', 'c33cd566-89db-55cf-8c76-1a85c317bd86', 19, '<p>$d$-ගොනුවේ මූල ද්‍රව්‍ය සම්බන්ධයෙන් පහත සඳහන් කුමන ප්‍රකාශය වැරදි වේද?</p>', '<p>$d$-ගොනුවේ මූල ද්‍රව්‍ය සම්බන්ධයෙන් පහත සඳහන් කුමන ප්‍රකාශය වැරදි වේද?</p>', NULL, '$ZnCl_2(aq)$ ට තනුක $NaOH$ එකතු කළ විට සෑදෙන සුදු පැහැති අවක්ෂේපය වන්නේ $Zn(OH)_2$ ය. $Zn(OH)_2$ යනු උභයගුණී (amphoteric) සංයෝගයක් වන බැවින් එය අම්ල මෙන්ම භස්ම සමගද ප්‍රතික්‍රියා කර ද්‍රවණය වේ. එබැවින් එය තනුක $HCl$ හි මනාව ද්‍රාව්‍ය වේ. "තනුක $HCl$ හි අද්‍රාව්‍ය වේ" යන ප්‍රකාශය වැරදි වේ.', '$ZnCl_2(aq)$ ට තනුක $NaOH$ එකතු කළ විට සෑදෙන සුදු පැහැති අවක්ෂේපය වන්නේ $Zn(OH)_2$ ය. $Zn(OH)_2$ යනු උභයගුණී (amphoteric) සංයෝගයක් වන බැවින් එය අම්ල මෙන්ම භස්ම සමගද ප්‍රතික්‍රියා කර ද්‍රවණය වේ. එබැවින් එය තනුක $HCl$ හි මනාව ද්‍රාව්‍ය වේ. "තනුක $HCl$ හි අද්‍රාව්‍ය වේ" යන ප්‍රකාශය වැරදි වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('cc00ceec-d79a-4c6c-a6f6-8755de7db8f8', '1bb7eab5-57dd-531a-8015-6818a0c918d1', '$V_2O_5$ ආම්ලික ඔක්සයිඩයක් වන අතර $VO$ භාස්මික ඔක්සයිඩයක් වේ.', '$V_2O_5$ ආම්ලික ඔක්සයිඩයක් වන අතර $VO$ භාස්මික ඔක්සයිඩයක් වේ.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('2133e662-1349-45ff-bed5-3313484ecfe8', '1bb7eab5-57dd-531a-8015-6818a0c918d1', '$Mn_3O_4$ හි, මැංගනීස් $Mn(II)$ සහ $Mn(III)$ හි මිශ්‍රණයක් ලෙස පවතී.', '$Mn_3O_4$ හි, මැංගනීස් $Mn(II)$ සහ $Mn(III)$ හි මිශ්‍රණයක් ලෙස පවතී.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('aa44f7aa-2ee0-4978-86a8-c6ac2d5f7243', '1bb7eab5-57dd-531a-8015-6818a0c918d1', '$Fe^{3+}$ සහ $Co^{2+}$ අඩංගු ජලීය ද්‍රාවණයකට $NH_4Cl/NH_4OH$ එකතු කළ විට $Fe^{3+}$ පමණක් අවක්ෂේප වේ.', '$Fe^{3+}$ සහ $Co^{2+}$ අඩංගු ජලීය ද්‍රාවණයකට $NH_4Cl/NH_4OH$ එකතු කළ විට $Fe^{3+}$ පමණක් අවක්ෂේප වේ.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('695d00f3-0f43-4658-899a-ad21079bd072', '1bb7eab5-57dd-531a-8015-6818a0c918d1', '$ZnCl_2(aq)$ ට තනුක $NaOH$ එකතු කිරීමෙන් සෑදෙන සුදු අවක්ෂේපය තනුක $HCl$ හි අද්‍රාව්‍ය වේ.', '$ZnCl_2(aq)$ ට තනුක $NaOH$ එකතු කිරීමෙන් සෑදෙන සුදු අවක්ෂේපය තනුක $HCl$ හි අද්‍රාව්‍ය වේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('a82bc0c6-ea55-453c-9186-d8bdc1ed828f', '1bb7eab5-57dd-531a-8015-6818a0c918d1', '$3d$ ආන්තරික ශ්‍රේණියෙහි පළමු මූල ද්‍රව්‍ය පහ ඒවායේ උපරිම ඔක්සිකරණ අවස්ථා ලබාගනුයේ සියලුම $4s$ හා $3d$ ඉලෙක්ට්‍රෝන පිටකිරීමෙනි.', '$3d$ ආන්තරික ශ්‍රේණියෙහි පළමු මූල ද්‍රව්‍ය පහ ඒවායේ උපරිම ඔක්සිකරණ අවස්ථා ලබාගනුයේ සියලුම $4s$ හා $3d$ ඉලෙක්ට්‍රෝන පිටකිරීමෙනි.', NULL, 'sanitized', 'v1', 4, 0);
