INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('72eaa262-d2fc-4a34-a1fb-8744590e5dbb', '239028d1-8cd8-57a0-816a-2c31af7dbd81', 'බෙන්සීන් ඩයසෝනියම් ක්ලෝරයිඩ් $+ CuCN \\rightarrow \\dots$
