INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('c7c5e69d-00b3-5b69-8846-f7e0cf31aa9e', 'c33cd566-89db-55cf-8c76-1a85c317bd86', 24, '<p>විවෘත බඳුනක් තුළ ඇති සංශුද්ධ ද්‍රවයක් රත් කිරීමේදී එය නැටීම (boiling) සිදුවන උෂ්ණත්වයේදී,</p>', '<p>විවෘත බඳුනක් තුළ ඇති සංශුද්ධ ද්‍රවයක් රත් කිරීමේදී එය නැටීම (boiling) සිදුවන උෂ්ණත්වයේදී,</p>', NULL, 'ද්‍රවයක් නැටීම (boiling) ආරම්භ වන්නේ, ද්‍රවයේ සංතෘප්ත වාෂ්ප පීඩනය බාහිර වායුගෝලීය පීඩනයට සමාන වූ විටදීය. එවිට ද්‍රවය අභ්‍යන්තරයේද වාෂ්ප බුබුළු සෑදී ඉහළට පැමිණිය හැක.', 'ද්‍රවයක් නැටීම (boiling) ආරම්භ වන්නේ, ද්‍රවයේ සංතෘප්ත වාෂ්ප පීඩනය බාහිර වායුගෝලීය පීඩනයට සමාන වූ විටදීය. එවිට ද්‍රවය අභ්‍යන්තරයේද වාෂ්ප බුබුළු සෑදී ඉහළට පැමිණිය හැක.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('57559ae2-042a-4b25-bc53-a56d5f405133', 'c7c5e69d-00b3-5b69-8846-f7e0cf31aa9e', 'ද්‍රවයෙහි මධ්‍ය චාලක ශක්තිය එහි වාෂ්පයෙහි මධ්‍ය චාලක ශක්තියට සමාන වේ.', 'ද්‍රවයෙහි මධ්‍ය චාලක ශක්තිය එහි වාෂ්පයෙහි මධ්‍ය චාලක ශක්තියට සමාන වේ.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('fdd6e8b1-2acc-407b-b8ad-5a38b8bba26a', 'c7c5e69d-00b3-5b69-8846-f7e0cf31aa9e', 'ද්‍රවයෙහි මධ්‍ය චාලක ශක්තිය එහි වාෂ්පයෙහි මවුලික එන්ට්‍රොපියට සමාන වේ.', 'ද්‍රවයෙහි මධ්‍ය චාලක ශක්තිය එහි වාෂ්පයෙහි මවුලික එන්ට්‍රොපියට සමාන වේ.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('32d8de5a-d7fc-42c2-bf21-b68f9c16fd0d', 'c7c5e69d-00b3-5b69-8846-f7e0cf31aa9e', 'ද්‍රවයෙහි එන්ට්‍රොපිය එහි වාෂ්පයේ එන්ට්‍රොපියට සමාන වේ.', 'ද්‍රවයෙහි එන්ට්‍රොපිය එහි වාෂ්පයේ එන්ට්‍රොපියට සමාන වේ.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('3f8af394-7caf-4490-82e2-8eeda17c0a43', 'c7c5e69d-00b3-5b69-8846-f7e0cf31aa9e', 'ද්‍රවයට ඉහළ ඇති වාෂ්පයෙහි එන්ට්‍රොපිය වායුගෝලයෙහි එන්ට්‍රොපියට සමාන වේ.', 'ද්‍රවයට ඉහළ ඇති වාෂ්පයෙහි එන්ට්‍රොපිය වායුගෝලයෙහි එන්ට්‍රොපියට සමාන වේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('142d9a75-5e78-4ab5-a1a6-aef7b8e61d6d', 'c7c5e69d-00b3-5b69-8846-f7e0cf31aa9e', 'ද්‍රවයෙහි වාෂ්ප පීඩනය ද්‍රව පෘෂ්ඨයට ඉහළින් ඇති වායුගෝල පීඩනයට සමාන වේ.', 'ද්‍රවයෙහි වාෂ්ප පීඩනය ද්‍රව පෘෂ්ඨයට ඉහළින් ඇති වායුගෝල පීඩනයට සමාන වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('7b311da5-eadf-5fee-bccb-b813a003595b', 'c33cd566-89db-55cf-8c76-1a85c317bd86', 25, '<p>$25^{\circ}C$ දී විද්‍යුත් රසායනික කෝෂයක් සඳහා පහත දැක්වෙන තොරතුරු සලකන්න.<br><br>අර්ධ ප්‍රතික්‍රියාව සහ අදාළ $E^{\circ} / V$ :<br>$Br_2(l) + 2e \rightleftharpoons 2Br^-(aq) \dots 1.065~V$<br>$BrO_3^-(aq) + 6H^+(aq) + 5e \rightleftharpoons \frac{1}{2}Br_2(l) + 3H_2O(l) \dots 1.520~V$<br><br>සම්පුර්ණ කෝෂ ප්‍රතික්‍රියාව, එයට අදාළ $E_{cell}^{\circ}$ සහ මාරුවන ඉලෙක්ට්‍රෝන සංඛ්‍යාව පහත සඳහන් කුමක් මගින් නිවැරදිව පෙන්නුම් කරයිද?</p>', '<p>$25^{\circ}C$ දී විද්‍යුත් රසායනික කෝෂයක් සඳහා පහත දැක්වෙන තොරතුරු සලකන්න.<br><br>අර්ධ ප්‍රතික්‍රියාව සහ අදාළ $E^{\circ} / V$ :<br>$Br_2(l) + 2e \rightleftharpoons 2Br^-(aq) \dots 1.065~V$<br>$BrO_3^-(aq) + 6H^+(aq) + 5e \rightleftharpoons \frac{1}{2}Br_2(l) + 3H_2O(l) \dots 1.520~V$<br><br>සම්පුර්ණ කෝෂ ප්‍රතික්‍රියාව, එයට අදාළ $E_{cell}^{\circ}$ සහ මාරුවන ඉලෙක්ට්‍රෝන සංඛ්‍යාව පහත සඳහන් කුමක් මගින් නිවැරදිව පෙන්නුම් කරයිද?</p>', NULL, 'විද්‍යුත් රසායනික කෝෂයක ස්වයංසිද්ධ ප්‍රතික්‍රියාවක් සඳහා $E_{cell}^{\circ} > 0$ විය යුතුය.<br>කැතෝඩය (ඔක්සිහරණය): $BrO_3^- + 6H^+ + 5e \rightleftharpoons \frac{1}{2}Br_2 + 3H_2O \dots E^{\circ} = 1.520~V$<br>ඇනෝඩය (ඔක්සිකරණය): $2Br^- \rightleftharpoons Br_2 + 2e \dots E^{\circ} = 1.065~V$<br>$E_{cell}^{\circ} = 1.520 - 1.065 = 0.455~V \approx 0.460~V$<br>ඉලෙක්ට්‍රෝන සංඛ්‍යාව තුලිත කිරීම සඳහා කැතෝඩ ප්‍රතික්‍රියාව 1 න් ද (5e), ඇනෝඩ ප්‍රතික්‍රියාව 2.5 න් ද (5e) ගුණ කළ හැක. එනම් මාරුවන මුළු ඉලෙක්ට්‍රෝන සංඛ්‍යාව 5 කි. ප්‍රතික්‍රියාව: $5Br^- + BrO_3^- + 6H^+ \rightleftharpoons 3Br_2 + 3H_2O$ වේ.', 'විද්‍යුත් රසායනික කෝෂයක ස්වයංසිද්ධ ප්‍රතික්‍රියාවක් සඳහා $E_{cell}^{\circ} > 0$ විය යුතුය.<br>කැතෝඩය (ඔක්සිහරණය): $BrO_3^- + 6H^+ + 5e \rightleftharpoons \frac{1}{2}Br_2 + 3H_2O \dots E^{\circ} = 1.520~V$<br>ඇනෝඩය (ඔක්සිකරණය): $2Br^- \rightleftharpoons Br_2 + 2e \dots E^{\circ} = 1.065~V$<br>$E_{cell}^{\circ} = 1.520 - 1.065 = 0.455~V \approx 0.460~V$<br>ඉලෙක්ට්‍රෝන සංඛ්‍යාව තුලිත කිරීම සඳහා කැතෝඩ ප්‍රතික්‍රියාව 1 න් ද (5e), ඇනෝඩ ප්‍රතික්‍රියාව 2.5 න් ද (5e) ගුණ කළ හැක. එනම් මාරුවන මුළු ඉලෙක්ට්‍රෝන සංඛ්‍යාව 5 කි. ප්‍රතික්‍රියාව: $5Br^- + BrO_3^- + 6H^+ \rightleftharpoons 3Br_2 + 3H_2O$ වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('9fd30f1a-434e-4a5f-bc6b-f4d7de5c03d9', '7b311da5-eadf-5fee-bccb-b813a003595b', 'සම්පූර්ණ ප්‍රතික්‍රියාව: $3Br_2(l) + 3H_2O(l) \rightleftharpoons 5Br^-(aq) + BrO_3^-(aq) + 6H^+(aq)$, $E^{\circ}: -0.460~V$, මාරුවන ඉලෙක්ට්‍රෝන සංඛ්‍යාව: 5', 'සම්පූර්ණ ප්‍රතික්‍රියාව: $3Br_2(l) + 3H_2O(l) \rightleftharpoons 5Br^-(aq) + BrO_3^-(aq) + 6H^+(aq)$, $E^{\circ}: -0.460~V$, මාරුවන ඉලෙක්ට්‍රෝන සංඛ්‍යාව: 5', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e07b2622-23d0-46d6-a03e-7bebff8f2f0b', '7b311da5-eadf-5fee-bccb-b813a003595b', 'සම්පූර්ණ ප්‍රතික්‍රියාව: $6Br_2(l) + 6H_2O(l) \rightleftharpoons 10Br^-(aq) + 2BrO_3^-(aq) + 12H^+(aq)$, $E^{\circ}: 0.920~V$, මාරුවන ඉලෙක්ට්‍රෝන සංඛ්‍යාව: 10', 'සම්පූර්ණ ප්‍රතික්‍රියාව: $6Br_2(l) + 6H_2O(l) \rightleftharpoons 10Br^-(aq) + 2BrO_3^-(aq) + 12H^+(aq)$, $E^{\circ}: 0.920~V$, මාරුවන ඉලෙක්ට්‍රෝන සංඛ්‍යාව: 10', NULL, 'sanitized', 'v1', 1, 0);
