INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('54ee7466-17cb-46ba-9a3a-97d16c1866db', '7b311da5-eadf-5fee-bccb-b813a003595b', 'සම්පූර්ණ ප්‍රතික්‍රියාව: $3Br_2(l) + 3H_2O(l) \rightleftharpoons 5Br^-(aq) + BrO_3^-(aq) + 6H^+(aq)$, $E^{\circ}: -0.920~V$, මාරුවන ඉලෙක්ට්‍රෝන සංඛ්‍යාව: 10', 'සම්පූර්ණ ප්‍රතික්‍රියාව: $3Br_2(l) + 3H_2O(l) \rightleftharpoons 5Br^-(aq) + BrO_3^-(aq) + 6H^+(aq)$, $E^{\circ}: -0.920~V$, මාරුවන ඉලෙක්ට්‍රෝන සංඛ්‍යාව: 10', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('c2d76446-c42c-40c7-9c43-6c819ae33843', '7b311da5-eadf-5fee-bccb-b813a003595b', 'සම්පූර්ණ ප්‍රතික්‍රියාව: $5Br^-(aq) + BrO_3^-(aq) + 6H^+(aq) \rightleftharpoons 3Br_2(l) + 3H_2O(l)$, $E^{\circ}: 0.460~V$, මාරුවන ඉලෙක්ට්‍රෝන සංඛ්‍යාව: 5', 'සම්පූර්ණ ප්‍රතික්‍රියාව: $5Br^-(aq) + BrO_3^-(aq) + 6H^+(aq) \rightleftharpoons 3Br_2(l) + 3H_2O(l)$, $E^{\circ}: 0.460~V$, මාරුවන ඉලෙක්ට්‍රෝන සංඛ්‍යාව: 5', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('c73c7680-87cd-5b53-bc3f-a77c25570cc4', 'c33cd566-89db-55cf-8c76-1a85c317bd86', 26, '<p>පහත සඳහන් ඔක්සිහරණ/ඔක්සිකරණ (Redox) යුග්ම ඒවායේ ඔක්සිහරණ විභවයන්හි අඩුවන පිළිවෙළට දී ඇත.<br>$O_2(g)/H_2O(l) > Br_2(l)/Br^-(aq) > I_2(s)/I^-(aq) > H^+(aq)/H_2(g) > Cd^{2+}(aq)/Cd(s) > Fe^{2+}(aq)/Fe(s) > Zn^{2+}(aq)/Zn(s) > Al^{3+}(aq)/Al(s)$<br><br>පහත දී ඇති කුමන ප්‍රතික්‍රියාව විද්‍යුත් රසායනික කෝෂයක් තුළ ස්වයං සිද්ධව සිදු නොවේද?</p>', '<p>පහත සඳහන් ඔක්සිහරණ/ඔක්සිකරණ (Redox) යුග්ම ඒවායේ ඔක්සිහරණ විභවයන්හි අඩුවන පිළිවෙළට දී ඇත.<br>$O_2(g)/H_2O(l) > Br_2(l)/Br^-(aq) > I_2(s)/I^-(aq) > H^+(aq)/H_2(g) > Cd^{2+}(aq)/Cd(s) > Fe^{2+}(aq)/Fe(s) > Zn^{2+}(aq)/Zn(s) > Al^{3+}(aq)/Al(s)$<br><br>පහත දී ඇති කුමන ප්‍රතික්‍රියාව විද්‍යුත් රසායනික කෝෂයක් තුළ ස්වයං සිද්ධව සිදු නොවේද?</p>', NULL, 'දී ඇති ශ්‍රේණියේ පහළින් ඇති මූලද්‍රව්‍යයකට ඉහළින් ඇති කැටායනයක්/ඔක්සිකාරකයක් ඔක්සිහරණය කළ හැක. 5 වන ප්‍රතික්‍රියාවේදී Fe මගින් $Al^{3+}$ ඔක්සිහරණය කිරීමට උත්සාහ කරයි. නමුත් Fe පිහිටන්නේ Al ට වඩා ඉහළින් බැවින් (එනම් $Fe^{2+}/Fe$ විභවය $Al^{3+}/Al$ ට වඩා වැඩිය), Fe වලට $Al^{3+}$ ඔක්සිහරණය කළ නොහැක. මෙම ප්‍රතික්‍රියාව ස්වයංසිද්ධ නොවේ.', 'දී ඇති ශ්‍රේණියේ පහළින් ඇති මූලද්‍රව්‍යයකට ඉහළින් ඇති කැටායනයක්/ඔක්සිකාරකයක් ඔක්සිහරණය කළ හැක. 5 වන ප්‍රතික්‍රියාවේදී Fe මගින් $Al^{3+}$ ඔක්සිහරණය කිරීමට උත්සාහ කරයි. නමුත් Fe පිහිටන්නේ Al ට වඩා ඉහළින් බැවින් (එනම් $Fe^{2+}/Fe$ විභවය $Al^{3+}/Al$ ට වඩා වැඩිය), Fe වලට $Al^{3+}$ ඔක්සිහරණය කළ නොහැක. මෙම ප්‍රතික්‍රියාව ස්වයංසිද්ධ නොවේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('11b3d9ca-477e-4f8a-9094-b0332cff47d9', 'c73c7680-87cd-5b53-bc3f-a77c25570cc4', '$Zn(s) + Cd^{2+}(aq) \longrightarrow Cd(s) + Zn^{2+}(aq)$', '$Zn(s) + Cd^{2+}(aq) \longrightarrow Cd(s) + Zn^{2+}(aq)$', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('1e241a13-f3f7-41d3-80dd-5d5e1131ff16', 'c73c7680-87cd-5b53-bc3f-a77c25570cc4', '$2Al(s) + 3Br_2(l) \longrightarrow 2Al^{3+}(aq) + 6Br^-(aq)$', '$2Al(s) + 3Br_2(l) \longrightarrow 2Al^{3+}(aq) + 6Br^-(aq)$', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('357f9ba9-db1e-4972-9c3a-c2fbcace256b', 'c73c7680-87cd-5b53-bc3f-a77c25570cc4', '$2H_2(g) + O_2(g) \longrightarrow 2H_2O(l)$', '$2H_2(g) + O_2(g) \longrightarrow 2H_2O(l)$', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('8c8d2948-e747-4b33-928f-87ddb7aa9311', 'c73c7680-87cd-5b53-bc3f-a77c25570cc4', '$H_2(g) + I_2(g) \longrightarrow 2H^+(aq) + 2I^-(aq)$', '$H_2(g) + I_2(g) \longrightarrow 2H^+(aq) + 2I^-(aq)$', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('aa6a506c-35e7-4910-b749-1717ce912a38', 'c73c7680-87cd-5b53-bc3f-a77c25570cc4', '$2Al^{3+}(aq) + 3Fe(s) \longrightarrow 2Al(s) + 3Fe^{2+}(aq)$', '$2Al^{3+}(aq) + 3Fe(s) \longrightarrow 2Al(s) + 3Fe^{2+}(aq)$', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('b9ede10f-0afa-5f5b-a0cc-c1379819f92c', 'c33cd566-89db-55cf-8c76-1a85c317bd86', 27, '<p>X සහ Y යනු $C_4H_8O$ අණුක සූත්‍රය සහිත සංයෝග දෙකකි. X සහ Y, ප්‍රතිකාරක තුනක් සමග ප්‍රතික්‍රියා කළ විට ලැබෙන නිරීක්ෂණ පහත වගුවේ දක්වා ඇත.<br><br>| ප්‍රතිකාරකය | X | Y |<br>| :--- | :--- | :--- |<br>| Na ලෝහය | වායුවක් පිටවිය | වායුවක් පිටවිය |<br>| 2, 4 - ඩයිනයිට්‍රෝෆීනයිල්හයිඩ්‍රසීන් | අවක්ෂේපයක් නැත | වර්ණවත් අවක්ෂේපයකි |<br>| $Br_2/H_2O$ | විවර්ණ විය | ප්‍රතික්‍රියාවක් නැත |<br><br>පහත දී ඇති ව්‍යුහ යුගල වලින් X හා Y පිළිවෙළින් විය හැක්කේ කුමක්ද?</p>
