INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('6cdc9741-a2a1-4164-8e7b-267f198b7408', 'bbaf848b-cf01-5381-a10e-e574f6e534f7', 'පළමු වැනි ප්‍රකාශය අසත්‍ය වේ. දෙවැනි ප්‍රකාශය අසත්‍ය වේ.', 'පළමු වැනි ප්‍රකාශය අසත්‍ය වේ. දෙවැනි ප්‍රකාශය අසත්‍ය වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('ba086c69-7a70-52b6-81ec-1c56fba59f4c', 'c33cd566-89db-55cf-8c76-1a85c317bd86', 45, '<p>පළමු වැනි ප්‍රකාශය: වායුගෝලීය ජල වාෂ්ප ගෝලීය උණුසුම ඉහළ යාමට දායක වේ.<br>දෙවැනි ප්‍රකාශය: ජල වාෂ්ප හරිතාගාර වායුවකි.</p>', '<p>පළමු වැනි ප්‍රකාශය: වායුගෝලීය ජල වාෂ්ප ගෝලීය උණුසුම ඉහළ යාමට දායක වේ.<br>දෙවැනි ප්‍රකාශය: ජල වාෂ්ප හරිතාගාර වායුවකි.</p>', NULL, 'ජල වාෂ්ප යනු පෘථිවිය මගින් පරාවර්තනය කරන අධෝරක්ත කිරණ (IR) අවශෝෂණය කළ හැකි ප්‍රබල හරිතාගාර වායුවකි. එය හරිතාගාර වායුවක් වීමම එය ගෝලීය උණුසුම ඉහළ යාමට ප්‍රධානතම හේතුවක් බව පැහැදිලි කරයි.', 'ජල වාෂ්ප යනු පෘථිවිය මගින් පරාවර්තනය කරන අධෝරක්ත කිරණ (IR) අවශෝෂණය කළ හැකි ප්‍රබල හරිතාගාර වායුවකි. එය හරිතාගාර වායුවක් වීමම එය ගෝලීය උණුසුම ඉහළ යාමට ප්‍රධානතම හේතුවක් බව පැහැදිලි කරයි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('bc9053ad-6a5d-49e6-91e3-cdbc1e7281c4', 'ba086c69-7a70-52b6-81ec-1c56fba59f4c', 'පළමු වැනි ප්‍රකාශය සත්‍ය වේ. දෙවැනි ප්‍රකාශය සත්‍ය වන අතර, පළමු වැනි ප්‍රකාශය නිවැරදිව පහදා දෙයි.', 'පළමු වැනි ප්‍රකාශය සත්‍ය වේ. දෙවැනි ප්‍රකාශය සත්‍ය වන අතර, පළමු වැනි ප්‍රකාශය නිවැරදිව පහදා දෙයි.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('45242f0d-c56c-45d1-9dbd-a28abf6edc9c', 'ba086c69-7a70-52b6-81ec-1c56fba59f4c', 'පළමු වැනි ප්‍රකාශය සත්‍ය වේ. දෙවැනි ප්‍රකාශය සත්‍ය වන නමුත් පළමු වැනි ප්‍රකාශය නිවැරදිව පහදා නොදෙයි.', 'පළමු වැනි ප්‍රකාශය සත්‍ය වේ. දෙවැනි ප්‍රකාශය සත්‍ය වන නමුත් පළමු වැනි ප්‍රකාශය නිවැරදිව පහදා නොදෙයි.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('b6efbfdc-c612-4bc9-a02e-db4f4b35a011', 'ba086c69-7a70-52b6-81ec-1c56fba59f4c', 'පළමු වැනි ප්‍රකාශය සත්‍ය වේ. දෙවැනි ප්‍රකාශය අසත්‍ය වේ.', 'පළමු වැනි ප්‍රකාශය සත්‍ය වේ. දෙවැනි ප්‍රකාශය අසත්‍ය වේ.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('0fc51433-7a42-4d38-89ee-57f8da52d51e', 'ba086c69-7a70-52b6-81ec-1c56fba59f4c', 'පළමු වැනි ප්‍රකාශය අසත්‍ය වේ. දෙවැනි ප්‍රකාශය සත්‍ය වේ.', 'පළමු වැනි ප්‍රකාශය අසත්‍ය වේ. දෙවැනි ප්‍රකාශය සත්‍ය වේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('901b909d-d8f6-414e-a05b-98d1e5e8d96d', 'ba086c69-7a70-52b6-81ec-1c56fba59f4c', 'පළමු වැනි ප්‍රකාශය අසත්‍ය වේ. දෙවැනි ප්‍රකාශය අසත්‍ය වේ.', 'පළමු වැනි ප්‍රකාශය අසත්‍ය වේ. දෙවැනි ප්‍රකාශය අසත්‍ය වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('17c8e6df-203f-51aa-9776-18ee43746650', 'c33cd566-89db-55cf-8c76-1a85c317bd86', 46, '<p>පළමු වැනි ප්‍රකාශය: ජලය සඳහා විලයනයේ එන්තැල්පිය $\Delta H_{fus}$ එහි වාෂ්පීකරණයේ එන්තැල්පියට $\Delta H_{vap}$ වඩා අඩුය.<br>දෙවැනි ප්‍රකාශය: වාෂ්පීකරණයට සාපේක්ෂව විලයනයේදී ජල අණු වඩා වැඩි දුරකට ඈත් වීම සිදු වේ.</p>', '<p>පළමු වැනි ප්‍රකාශය: ජලය සඳහා විලයනයේ එන්තැල්පිය $\Delta H_{fus}$ එහි වාෂ්පීකරණයේ එන්තැල්පියට $\Delta H_{vap}$ වඩා අඩුය.<br>දෙවැනි ප්‍රකාශය: වාෂ්පීකරණයට සාපේක්ෂව විලයනයේදී ජල අණු වඩා වැඩි දුරකට ඈත් වීම සිදු වේ.</p>', NULL, 'ජලයේ විලයන එන්තැල්පිය $\approx 6~kJ~mol^{-1}$ වන අතර වාෂ්පීකරණ එන්තැල්පිය $\approx 41~kJ~mol^{-1}$ වේ (පළමු ප්‍රකාශය සත්‍යයකි). වාෂ්පීකරණයේදී (ද්‍රවයේ සිට වායුවට) අණු අතර දුර ඉතා විශාල වශයෙන් වැඩි වන අතර, විලයනයේදී (ඝනයේ සිට ද්‍රවයට) අණු අතර දුර වෙනස් වන්නේ සුළු වශයෙනි. එබැවින් ''වාෂ්පීකරණයට සාපේක්ෂව විලයනයේදී අණු වැඩි දුරකට ඈත් වේ'' යන දෙවන ප්‍රකාශය අසත්‍ය වේ.', 'ජලයේ විලයන එන්තැල්පිය $\approx 6~kJ~mol^{-1}$ වන අතර වාෂ්පීකරණ එන්තැල්පිය $\approx 41~kJ~mol^{-1}$ වේ (පළමු ප්‍රකාශය සත්‍යයකි). වාෂ්පීකරණයේදී (ද්‍රවයේ සිට වායුවට) අණු අතර දුර ඉතා විශාල වශයෙන් වැඩි වන අතර, විලයනයේදී (ඝනයේ සිට ද්‍රවයට) අණු අතර දුර වෙනස් වන්නේ සුළු වශයෙනි. එබැවින් ''වාෂ්පීකරණයට සාපේක්ෂව විලයනයේදී අණු වැඩි දුරකට ඈත් වේ'' යන දෙවන ප්‍රකාශය අසත්‍ය වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('f2f4ae78-dd28-47bc-9531-0477a8de5a75', '17c8e6df-203f-51aa-9776-18ee43746650', 'පළමු වැනි ප්‍රකාශය සත්‍ය වේ. දෙවැනි ප්‍රකාශය සත්‍ය වන අතර, පළමු වැනි ප්‍රකාශය නිවැරදිව පහදා දෙයි.', 'පළමු වැනි ප්‍රකාශය සත්‍ය වේ. දෙවැනි ප්‍රකාශය සත්‍ය වන අතර, පළමු වැනි ප්‍රකාශය නිවැරදිව පහදා දෙයි.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('a8d27205-bc0c-41aa-bc00-8d076a30a566', '17c8e6df-203f-51aa-9776-18ee43746650', 'පළමු වැනි ප්‍රකාශය සත්‍ය වේ. දෙවැනි ප්‍රකාශය සත්‍ය වන නමුත් පළමු වැනි ප්‍රකාශය නිවැරදිව පහදා නොදෙයි.', 'පළමු වැනි ප්‍රකාශය සත්‍ය වේ. දෙවැනි ප්‍රකාශය සත්‍ය වන නමුත් පළමු වැනි ප්‍රකාශය නිවැරදිව පහදා නොදෙයි.', NULL, 'sanitized', 'v1', 1, 0);
