INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('42f59f46-3d46-4c93-abdc-c7c725377565', '0377ee8c-c158-5053-b490-80426824e823', 'ඉස්සෙල්ලා ආපු කනට වඩා පස්සෙ ආපු අඟ ලොකු වුණා වගේ.', 'ඉස්සෙල්ලා ආපු කනට වඩා පස්සෙ ආපු අඟ ලොකු වුණා වගේ.', NULL, 'sanitized', 'v1', 1, 0);
