INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('17d61958-e391-4d2f-a000-e602e6347cba', '158f1d63-a888-5610-95ec-4e70ab7f13da', 'වත්ත බද්දට දී ඇස්සට දත නියවනවා ලු.', 'වත්ත බද්දට දී ඇස්සට දත නියවනවා ලු.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('ca8b9884-fe50-455a-81fc-a62fe53b0396', '158f1d63-a888-5610-95ec-4e70ab7f13da', 'කලක දී වහලු කලක දි රහ වෙනවා ලු.', 'කලක දී වහලු කලක දි රහ වෙනවා ලු.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('3824c576-28a8-4a2e-a3ba-58a4b87246c8', '158f1d63-a888-5610-95ec-4e70ab7f13da', 'ඌරො කැකුණ තළන කොට හබන් කුකුළන්ට රජ මඟුල් ලු.', 'ඌරො කැකුණ තළන කොට හබන් කුකුළන්ට රජ මඟුල් ලු.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('f0a2a619-005f-5f7b-a940-4b8cb1af801c', 'c8e8f0aa-e104-5525-80d1-f080c49bbe89', 28, '<p>ද්විත්ව රූප හා පරරූප සන්ධියට අදාළ නිදසුන් පිළිවෙළින් දැක්වෙන වරණය තෝරන්න.</p>', '<p>ද්විත්ව රූප හා පරරූප සන්ධියට අදාළ නිදසුන් පිළිවෙළින් දැක්වෙන වරණය තෝරන්න.</p>', NULL, '''සන් + අස් = සන්නස්'' (ද්විත්ව රූප සන්ධි) සහ ''අත් + දැකීම = අද්දැකීම'' (පරරූප සන්ධි - පෙර පදයේ අග අකුර පර පදයේ මුල් අකුරේ ස්වරූපය ගැනීම) නිවැරදි වේ.', '''සන් + අස් = සන්නස්'' (ද්විත්ව රූප සන්ධි) සහ ''අත් + දැකීම = අද්දැකීම'' (පරරූප සන්ධි - පෙර පදයේ අග අකුර පර පදයේ මුල් අකුරේ ස්වරූපය ගැනීම) නිවැරදි වේ.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
