INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('d2cc4835-5d2c-4ff7-a578-b56f46dddc5f', '695d9e5d-a7bf-5096-981f-9fe4cb2efe7e', 'උත්ප්‍රේක්ෂාලංකාරයයි.', 'උත්ප්‍රේක්ෂාලංකාරයයි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('1180ccc3-4bd4-50de-9e82-9e83d173496d', 'c8e8f0aa-e104-5525-80d1-f080c49bbe89', 36, '<p>ශ්‍රීමත් අයිවර් ජෙනිංග්ස් මහතා සම්බන්ධයෙන් නිවැරදි ප්‍රකාශය කුමක්ද?</p>', '<p>ශ්‍රීමත් අයිවර් ජෙනිංග්ස් මහතා සම්බන්ධයෙන් නිවැරදි ප්‍රකාශය කුමක්ද?</p>', NULL, 'ශ්‍රීමත් අයිවර් ජෙනිංග්ස් (Sir Ivor Jennings) යනු ශ්‍රී ලංකාවේ ප්‍රථම විශ්වවිද්‍යාලය වන ලංකා විශ්වවිද්‍යාලයේ (University of Ceylon) පළමු උපකුලපතිවරයා හා එහි නිර්මාතෘවරයාය.', 'ශ්‍රීමත් අයිවර් ජෙනිංග්ස් (Sir Ivor Jennings) යනු ශ්‍රී ලංකාවේ ප්‍රථම විශ්වවිද්‍යාලය වන ලංකා විශ්වවිද්‍යාලයේ (University of Ceylon) පළමු උපකුලපතිවරයා හා එහි නිර්මාතෘවරයාය.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('7a203f72-1350-46dc-8724-822604dfc332', '1180ccc3-4bd4-50de-9e82-9e83d173496d', 'ශ්‍රී ලංකාවේ ජුරාසික යුගය පිළිබඳ තොරතුරු ඉදිරිපත් කළ පුරාවිද්‍යාඥයා ය.', 'ශ්‍රී ලංකාවේ ජුරාසික යුගය පිළිබඳ තොරතුරු ඉදිරිපත් කළ පුරාවිද්‍යාඥයා ය.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('c4418de1-2fa8-4caa-96a0-90ce5cc5bed3', '1180ccc3-4bd4-50de-9e82-9e83d173496d', 'ශ්‍රී ලංකාවේ විශ්ව විද්‍යාල අධ්‍යාපනයේ නිර්මාතෘවරයා ය.', 'ශ්‍රී ලංකාවේ විශ්ව විද්‍යාල අධ්‍යාපනයේ නිර්මාතෘවරයා ය.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('f8a07827-92cf-4509-9aea-da8b9f127009', '1180ccc3-4bd4-50de-9e82-9e83d173496d', 'පෙරසවි කොන්ක්‍රීට් තාක්ෂණය ලෝකයට හඳුන්වා දුන් ඉංජිනේරුවරයා ය.', 'පෙරසවි කොන්ක්‍රීට් තාක්ෂණය ලෝකයට හඳුන්වා දුන් ඉංජිනේරුවරයා ය.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('9d06bb3b-3304-429f-8af3-41462d7a6c02', '1180ccc3-4bd4-50de-9e82-9e83d173496d', 'ජාතික ඖෂධ ප්‍රතිපත්තියක් හඳුන්වාදීමට ක්‍රියා කළ විද්වතාය.', 'ජාතික ඖෂධ ප්‍රතිපත්තියක් හඳුන්වාදීමට ක්‍රියා කළ විද්වතාය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('59e3bb8d-09f7-53bc-b0a3-24f55ac7fdda', 'c8e8f0aa-e104-5525-80d1-f080c49bbe89', 37, '<p>''වගතුග'' නම් තීරු ලිපි මාලාවේ රචකයා කවරෙක් ද?</p>', '<p>''වගතුග'' නම් තීරු ලිපි මාලාවේ රචකයා කවරෙක් ද?</p>', NULL, '''වගතුග'' තීරු ලිපි මාලාව ලංකාදීප පුවත්පතට රචනා කරන ලද්දේ ප්‍රවීණ පුවත්පත් කලාවේදියෙකු හා කවියෙකු වූ ශ්‍රී චන්ද්‍රරත්න මානවසිංහයන් විසිනි.', '''වගතුග'' තීරු ලිපි මාලාව ලංකාදීප පුවත්පතට රචනා කරන ලද්දේ ප්‍රවීණ පුවත්පත් කලාවේදියෙකු හා කවියෙකු වූ ශ්‍රී චන්ද්‍රරත්න මානවසිංහයන් විසිනි.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
