INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('7635b76f-f8ee-5a13-829d-97af560c7b7a', 'c8e8f0aa-e104-5525-80d1-f080c49bbe89', 38, '<p>කුඹුරු ගොවිතැනේදී වෑදම යනුවෙන් හඳුන්වන්නේ,</p>', '<p>කුඹුරු ගොවිතැනේදී වෑදම යනුවෙන් හඳුන්වන්නේ,</p>', NULL, 'ගොයම් කැපීම වැනි කෘෂිකාර්මික කටයුතු වල නියැලෙන්නන් සඳහා කෙත් යායේදීම ලබාදෙන ආහාරපාන සංග්‍රහය ''වෑදම'' ලෙස ගොවි වහරේ හැඳින්වේ.', 'ගොයම් කැපීම වැනි කෘෂිකාර්මික කටයුතු වල නියැලෙන්නන් සඳහා කෙත් යායේදීම ලබාදෙන ආහාරපාන සංග්‍රහය ''වෑදම'' ලෙස ගොවි වහරේ හැඳින්වේ.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('91d8bab0-3210-4f4b-abe7-f8b9d9423ac3', '7635b76f-f8ee-5a13-829d-97af560c7b7a', 'ගොයම් කැපීමේදී භාවිත කරන දෑකැත්ත යි.', 'ගොයම් කැපීමේදී භාවිත කරන දෑකැත්ත යි.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e132e84c-0c4a-4329-8b59-ef4b99905900', '7635b76f-f8ee-5a13-829d-97af560c7b7a', 'ගොයම් කපන අවස්ථාවේ පිරිනමන ආහාරයි.', 'ගොයම් කපන අවස්ථාවේ පිරිනමන ආහාරයි.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('7a669673-b73b-440f-91c9-ee21a6eb0f6c', '7635b76f-f8ee-5a13-829d-97af560c7b7a', 'ගොයම් එකතු කිරීමට භාවිත කරන පැදුර යි.', 'ගොයම් එකතු කිරීමට භාවිත කරන පැදුර යි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('5b6a63c9-6975-4d82-a21f-f7a58cae9a7e', '7635b76f-f8ee-5a13-829d-97af560c7b7a', 'කමතේ දී සිදු කරන වතාවත් සඳහා භාවිත කරන පූජා භාණ්ඩයි.', 'කමතේ දී සිදු කරන වතාවත් සඳහා භාවිත කරන පූජා භාණ්ඩයි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('de9da8b4-4809-5421-9391-a3323122b924', 'c8e8f0aa-e104-5525-80d1-f080c49bbe89', 39, '<p>''''කසාද කාසිත් ගෙවපු නිසා ඉලන්දාරි ගෑනු ළමයගෙන් යමක් අහන්න තියෙනවා මට'''' හුනුවටයේ කතාවේ එන ඉහත ප්‍රකාශය කරන්නේ කවරකුද?</p>', '<p>''''කසාද කාසිත් ගෙවපු නිසා ඉලන්දාරි ගෑනු ළමයගෙන් යමක් අහන්න තියෙනවා මට'''' හුනුවටයේ කතාවේ එන ඉහත ප්‍රකාශය කරන්නේ කවරකුද?</p>', NULL, 'මෙම දෙබස හෙන්රි ජයසේනයන්ගේ ''හුනුවටයේ කතාව'' නාට්‍යයේ එන සයිමන් ෂෂාවා (ගෘෂාගේ පෙම්වතා) විසින් සිදු කරන ලද්දකි.', 'මෙම දෙබස හෙන්රි ජයසේනයන්ගේ ''හුනුවටයේ කතාව'' නාට්‍යයේ එන සයිමන් ෂෂාවා (ගෘෂාගේ පෙම්වතා) විසින් සිදු කරන ලද්දකි.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
