INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('bc9e12b1-3b94-5d9a-b962-a707800efb6e', 'c8e8f0aa-e104-5525-80d1-f080c49bbe89', 40, '<p>පහත සඳහන් පාඨයේ අර්ථයට වඩාත් සමීප අදහස දෙන පිළිතුර තෝරන්න.<br><br>''සංස්කෘතියක් නියෝජනය කරන සහ නිරූපණය කරන ප්‍රධාන මෙවලම වන්නේ භාෂාව යි. ඊළඟ පරම්පරාවට සංස්කෘතිය ගෙන යන්නේ ද භාෂාව මගිනි. ඒ අනුව භාෂාව හා සංස්කෘතිය අතර ඇත්තේ අවියෝජනීය සම්බන්ධතාවකි.''</p>', '<p>පහත සඳහන් පාඨයේ අර්ථයට වඩාත් සමීප අදහස දෙන පිළිතුර තෝරන්න.<br><br>''සංස්කෘතියක් නියෝජනය කරන සහ නිරූපණය කරන ප්‍රධාන මෙවලම වන්නේ භාෂාව යි. ඊළඟ පරම්පරාවට සංස්කෘතිය ගෙන යන්නේ ද භාෂාව මගිනි. ඒ අනුව භාෂාව හා සංස්කෘතිය අතර ඇත්තේ අවියෝජනීය සම්බන්ධතාවකි.''</p>', NULL, 'මුල් ඡේදයේ සඳහන් වන ''නියෝජනය'', ''නිරූපණය'', ''පරම්පරාවට ගෙනයාම'' සහ ''අවියෝජනීය සම්බන්ධතාව'' යන සියලුම ප්‍රධාන අදහස් වඩාත් තර්කානුකූලව ගැබ් වී ඇත්තේ පළමු පිළිතුරේය.', 'මුල් ඡේදයේ සඳහන් වන ''නියෝජනය'', ''නිරූපණය'', ''පරම්පරාවට ගෙනයාම'' සහ ''අවියෝජනීය සම්බන්ධතාව'' යන සියලුම ප්‍රධාන අදහස් වඩාත් තර්කානුකූලව ගැබ් වී ඇත්තේ පළමු පිළිතුරේය.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('8e4725d0-1006-4a1b-850a-604ec512f6e1', 'bc9e12b1-3b94-5d9a-b962-a707800efb6e', 'භාෂාව හා සංස්කෘතිය අතර ඇති නොබිඳෙන සබඳතාවට සාක්ෂ්‍ය සපයන ප්‍රධාන සාධක වන්නේ භාෂාව මගින් සංස්කෘතිය නියෝජනය කිරීම සහ පරම්පරාවෙන් පරම්පරාවට සංස්කෘතිය ගෙන යන වාහකය භාෂාව වීම යි.', 'භාෂාව හා සංස්කෘතිය අතර ඇති නොබිඳෙන සබඳතාවට සාක්ෂ්‍ය සපයන ප්‍රධාන සාධක වන්නේ භාෂාව මගින් සංස්කෘතිය නියෝජනය කිරීම සහ පරම්පරාවෙන් පරම්පරාවට සංස්කෘතිය ගෙන යන වාහකය භාෂාව වීම යි.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('d95475d4-6eed-462f-881a-e4c1e57484ee', 'bc9e12b1-3b94-5d9a-b962-a707800efb6e', 'සංස්කෘතියක් නියෝජනය කරන හා නිරූපණය කරන භාෂාව සංස්කෘතියේ වාහකය වන අතර භාෂාව හා සංස්කෘතිය අතර ඇත්තේ නොබිඳෙන සබඳතාවකි.', 'සංස්කෘතියක් නියෝජනය කරන හා නිරූපණය කරන භාෂාව සංස්කෘතියේ වාහකය වන අතර භාෂාව හා සංස්කෘතිය අතර ඇත්තේ නොබිඳෙන සබඳතාවකි.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('cdb04ad2-0b3a-4ae6-9470-7bb6b24c8610', 'bc9e12b1-3b94-5d9a-b962-a707800efb6e', 'සංස්කෘතියේ වාහකය භාෂාව වන අතර එනිසා ම භාෂාව මගින් සංස්කෘතිය නිරූපණය කිරීමත් නියෝජනය කිරීමත් නොබිඳෙන සබඳතාවක් පවත්වා ගැනීමත් සිදු කරයි.', 'සංස්කෘතියේ වාහකය භාෂාව වන අතර එනිසා ම භාෂාව මගින් සංස්කෘතිය නිරූපණය කිරීමත් නියෝජනය කිරීමත් නොබිඳෙන සබඳතාවක් පවත්වා ගැනීමත් සිදු කරයි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('a462d3fa-28ae-4eb5-aabe-44ac0198dc54', 'bc9e12b1-3b94-5d9a-b962-a707800efb6e', 'සංස්කෘතියේ නිරූපණයත් නියෝජනයත් සිදු කරන භාෂාව සංස්කෘතියේ වාහකයා වශයෙන් ද ක්‍රියාත්මක වේ.', 'සංස්කෘතියේ නිරූපණයත් නියෝජනයත් සිදු කරන භාෂාව සංස්කෘතියේ වාහකයා වශයෙන් ද ක්‍රියාත්මක වේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('2e499907-cc4d-586e-92a8-46f2709ee4fa', 'ceb7f686-6434-5783-8d87-3779dbdf9633', 1, '<p>$-5 \times (-4) - 1$ හි අගය සොයන්න.</p>', '<p>$-5 \times (-4) - 1$ හි අගය සොයන්න.</p>', NULL, '<p>$-5 \times (-4) = 20$, 20 - 1 = 19</p>', '<p>$-5 \times (-4) = 20$, 20 - 1 = 19</p>', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
