INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('36660076-ad15-50cf-bdcb-650444d3a67b', 'ceb7f686-6434-5783-8d87-3779dbdf9633', 2, '<p>$\frac{1}{4} + \frac{1}{8}$ සුළු කරන්න.</p>', '<p>$\frac{1}{4} + \frac{1}{8}$ සුළු කරන්න.</p>', NULL, '<p>හරයන් සමාන කළ විට $\frac{2}{8} + \frac{1}{8} = \frac{3}{8}$ වේ.</p>', '<p>හරයන් සමාන කළ විට $\frac{2}{8} + \frac{1}{8} = \frac{3}{8}$ වේ.</p>', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
