INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('7b5d6dad-e649-5055-91cf-5f3f651b6d34', 'ceb7f686-6434-5783-8d87-3779dbdf9633', 9, '<p>$2^2 \times 2^1$ සුළු කරන්න.</p>', '<p>$2^2 \times 2^1$ සුළු කරන්න.</p>', NULL, '<p>දර්ශක නීති වලට අනුව, $a^m \times a^n = a^{m+n}$. එබැවින් $2^2 \times 2^1 = 2^{2+1} = 2^3$.</p>', '<p>දර්ශක නීති වලට අනුව, $a^m \times a^n = a^{m+n}$. එබැවින් $2^2 \times 2^1 = 2^{2+1} = 2^3$.</p>', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('5626dd05-fd83-4361-856e-58781a653c93', '7b5d6dad-e649-5055-91cf-5f3f651b6d34', '$2^3$', '$2^3$', NULL, 'sanitized', 'v1', 0, 1);
