INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('71870297-8613-53e8-9e96-b6207c5ae963', 'ceb7f686-6434-5783-8d87-3779dbdf9633', 10, '<p>සෘජුකෝණී ත්‍රිකෝණයක, කෝණයකට සම්මුඛ පාදය $3$ ද, බද්ධ පාදය $4$ ද වේ නම් කර්ණයෙහි දිග කොපමණද?</p>', '<p>සෘජුකෝණී ත්‍රිකෝණයක, කෝණයකට සම්මුඛ පාදය $3$ ද, බද්ධ පාදය $4$ ද වේ නම් කර්ණයෙහි දිග කොපමණද?</p>', NULL, '<p>පයිතගරස් ප්‍රමේයයට අනුව, කර්ණය$^2 = 3^2 + 4^2 = 9 + 16 = 25$. එබැවින් කර්ණය $= \sqrt{25} = 5$.</p>', '<p>පයිතගරස් ප්‍රමේයයට අනුව, කර්ණය$^2 = 3^2 + 4^2 = 9 + 16 = 25$. එබැවින් කර්ණය $= \sqrt{25} = 5$.</p>', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
