INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('1e3c870b-63ba-5ad5-8ad4-1b855b5523d9', 'ceb7f686-6434-5783-8d87-3779dbdf9633', 25, '<p>$2x + 3 = 9$ නම් $x$ හි අගය සොයන්න.</p>', '<p>$2x + 3 = 9$ නම් $x$ හි අගය සොයන්න.</p>', NULL, '<p>$2x = 9 - 3 = 6$. එබැවින් $x = \frac{6}{2} = 3$.</p>', '<p>$2x = 9 - 3 = 6$. එබැවින් $x = \frac{6}{2} = 3$.</p>', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
