INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('679062a0-92f2-53d0-ac10-42c4c69b2fd6', 'd2b54663-8d63-56fa-a512-dca908a85bdd', 1, '<p>Electron volt (eV) is a unit of</p>', '<p>Electron volt (eV) is a unit of</p>', NULL, '$1\ eV$ is the amount of kinetic energy gained by a single electron accelerating from rest through an electric potential difference of one volt. Therefore, it is a unit of energy.', '$1\ eV$ is the amount of kinetic energy gained by a single electron accelerating from rest through an electric potential difference of one volt. Therefore, it is a unit of energy.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
