INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('c7c0fae7-48d2-5fee-a713-38c76734f8ad', 'd2b54663-8d63-56fa-a512-dca908a85bdd', 2, '<p>The distance between the centers of two uniform spherical masses $M$ and $m$ is $r$. What is the gravitational potential energy of the two masses?</p>', '<p>The distance between the centers of two uniform spherical masses $M$ and $m$ is $r$. What is the gravitational potential energy of the two masses?</p>', NULL, 'The gravitational potential energy between two spherical masses is always negative (indicating an attractive force) and is inversely proportional to the distance $r$. It is given by the formula $U = -\frac{GMm}{r}$.', 'The gravitational potential energy between two spherical masses is always negative (indicating an attractive force) and is inversely proportional to the distance $r$. It is given by the formula $U = -\frac{GMm}{r}$.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
