INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('3e0062ae-197c-50f3-8b3c-492a858c3435', 'd2b54663-8d63-56fa-a512-dca908a85bdd', 5, '<p>Longitudinal waves do not exhibit</p>', '<p>Longitudinal waves do not exhibit</p>', NULL, 'Polarization is a property exclusive to transverse waves, where oscillations are restricted to a single plane perpendicular to the direction of propagation. Longitudinal waves oscillate parallel to propagation and cannot be polarized.', 'Polarization is a property exclusive to transverse waves, where oscillations are restricted to a single plane perpendicular to the direction of propagation. Longitudinal waves oscillate parallel to propagation and cannot be polarized.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
