INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('c07d2dd2-a4b5-5e44-9598-1a2722ff00e5', 'd2b54663-8d63-56fa-a512-dca908a85bdd', 6, '<p>If the absolute temperature of a blackbody is increased by 2 times, the energy radiated by the blackbody per unit time per unit area will increase by</p>', '<p>If the absolute temperature of a blackbody is increased by 2 times, the energy radiated by the blackbody per unit time per unit area will increase by</p>', NULL, 'According to the Stefan-Boltzmann law, the radiated power per unit area is proportional to the fourth power of the absolute temperature ($E \propto T^4$). If $T$ doubles, energy increases by $2^4 = 16$ times.', 'According to the Stefan-Boltzmann law, the radiated power per unit area is proportional to the fourth power of the absolute temperature ($E \propto T^4$). If $T$ doubles, energy increases by $2^4 = 16$ times.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
