INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('c5d64fbd-4967-57da-b9ae-961676e93eeb', 'd2b54663-8d63-56fa-a512-dca908a85bdd', 8, '<p>What is the quark composition of a neutron (n)?</p>', '<p>What is the quark composition of a neutron (n)?</p>', NULL, 'A neutron is a baryon composed of one up quark (charge $+2/3 e$) and two down quarks (charge $-1/3 e$), giving a net electrical charge of $0$ ($udd$).', 'A neutron is a baryon composed of one up quark (charge $+2/3 e$) and two down quarks (charge $-1/3 e$), giving a net electrical charge of $0$ ($udd$).', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
