INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('bd6a0b25-7ec0-5b38-97a2-db1c9885fc9f', 'd2b54663-8d63-56fa-a512-dca908a85bdd', 9, '<p>If the pressure of a given mass of an ideal gas is kept constant, the variation of its density $\rho$ with the absolute temperature $T$ is best represented by</p>', '<p>If the pressure of a given mass of an ideal gas is kept constant, the variation of its density $\rho$ with the absolute temperature $T$ is best represented by</p>', NULL, 'From the ideal gas law $P = \frac{\rho R T}{M}$, we get $\rho = \left(\frac{PM}{R}\right) \frac{1}{T}$. Thus, density is inversely proportional to temperature ($\rho \propto 1/T$), which is represented by a curve with a decreasing negative slope in the first quadrant.', 'From the ideal gas law $P = \frac{\rho R T}{M}$, we get $\rho = \left(\frac{PM}{R}\right) \frac{1}{T}$. Thus, density is inversely proportional to temperature ($\rho \propto 1/T$), which is represented by a curve with a decreasing negative slope in the first quadrant.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
