INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('cfb71d91-809b-511b-92cc-6bafcb30167b', 'd2b54663-8d63-56fa-a512-dca908a85bdd', 10, '<p>Three thermodynamic processes are given below.<br>(A) an isothermal process<br>(B) a constant volume process<br>(C) a constant pressure process<br><br>All the heat energy supplied to an ideal gas is converted to work done by the gas</p>', '<p>Three thermodynamic processes are given below.<br>(A) an isothermal process<br>(B) a constant volume process<br>(C) a constant pressure process<br><br>All the heat energy supplied to an ideal gas is converted to work done by the gas</p>', NULL, 'According to the first law of thermodynamics, $\Delta Q = \Delta U + \Delta W$. If all heat is converted to work ($\Delta Q = \Delta W$), then $\Delta U = 0$. For an ideal gas, $\Delta U = 0$ implies constant temperature, which corresponds exclusively to an isothermal process.', 'According to the first law of thermodynamics, $\Delta Q = \Delta U + \Delta W$. If all heat is converted to work ($\Delta Q = \Delta W$), then $\Delta U = 0$. For an ideal gas, $\Delta U = 0$ implies constant temperature, which corresponds exclusively to an isothermal process.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
