INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('906d9b5b-20c7-5a1b-8f39-9fd4dc1d5028', 'd2b54663-8d63-56fa-a512-dca908a85bdd', 11, '<p>Electric potential of two conducting parallel plates are $-10\ V$ and $30\ V$ respectively. If the separation between the plates is $2\ cm$ what is the electric field intensity between the plates?</p>', '<p>Electric potential of two conducting parallel plates are $-10\ V$ and $30\ V$ respectively. If the separation between the plates is $2\ cm$ what is the electric field intensity between the plates?</p>', NULL, 'The electric field intensity is given by $E = \frac{\Delta V}{d} = \frac{30 - (-10)}{0.02\ m} = \frac{40}{0.02} = 2000\ V\ m^{-1}$.', 'The electric field intensity is given by $E = \frac{\Delta V}{d} = \frac{30 - (-10)}{0.02\ m} = \frac{40}{0.02} = 2000\ V\ m^{-1}$.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
