INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('9545d6aa-9d2f-5b02-8126-c00e5f4d288f', 'd2b54663-8d63-56fa-a512-dca908a85bdd', 12, '<p>Which of following is not true about the electric field lines?</p>', '<p>Which of following is not true about the electric field lines?</p>', NULL, 'Unlike magnetic field lines, electrostatic field lines do not form closed loops. They originate from positive charges and terminate on negative charges (or extend to infinity).', 'Unlike magnetic field lines, electrostatic field lines do not form closed loops. They originate from positive charges and terminate on negative charges (or extend to infinity).', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('0a85c9d9-5e18-4e93-9b81-bdefa0d72baf', '9545d6aa-9d2f-5b02-8126-c00e5f4d288f', 'Field lines start from positive charges and end at negative charges.', 'Field lines start from positive charges and end at negative charges.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('23b728d5-cbe4-4708-9adc-c31359e384bd', '9545d6aa-9d2f-5b02-8126-c00e5f4d288f', 'If a single positive charge exists field lines end at infinity.', 'If a single positive charge exists field lines end at infinity.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('ec564e3b-dc23-44e5-a4bb-cd82e085ed88', '9545d6aa-9d2f-5b02-8126-c00e5f4d288f', 'Two field lines can never cross each other.', 'Two field lines can never cross each other.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('12b649be-4f78-4022-8d8a-068f3e6092bf', '9545d6aa-9d2f-5b02-8126-c00e5f4d288f', 'Electrostatic field lines form closed loops.', 'Electrostatic field lines form closed loops.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('0aa9b27a-81c8-419d-9cda-0c52f2523ace', '9545d6aa-9d2f-5b02-8126-c00e5f4d288f', 'Field lines are imaginary lines which are used to represent the pattern of an electric field.', 'Field lines are imaginary lines which are used to represent the pattern of an electric field.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('7f6f3b5c-2829-5945-a4d3-9add0156cdab', 'd2b54663-8d63-56fa-a512-dca908a85bdd', 13, '<p>A sound source of intensity $I_{1}$ produces a sound intensity level of $90\ dB$ at a certain point. Another sound source of intensity $I_{2}$ produces a sound intensity level of $40\ dB$ at the same point. The distance from both the sources to the point is same. What is the ratio of $\frac{I_{1}}{I_{2}}$?</p>', '<p>A sound source of intensity $I_{1}$ produces a sound intensity level of $90\ dB$ at a certain point. Another sound source of intensity $I_{2}$ produces a sound intensity level of $40\ dB$ at the same point. The distance from both the sources to the point is same. What is the ratio of $\frac{I_{1}}{I_{2}}$?</p>', NULL, 'The difference in sound intensity levels is $\Delta \beta = 90\ dB - 40\ dB = 50\ dB$. Since $\Delta \beta = 10 \log_{10} \left(\frac{I_1}{I_2}\right)$, we have $50 = 10 \log_{10} \left(\frac{I_1}{I_2}\right) \implies 5 = \log_{10} \left(\frac{I_1}{I_2}\right) \implies \frac{I_1}{I_2} = 10^5$.', 'The difference in sound intensity levels is $\Delta \beta = 90\ dB - 40\ dB = 50\ dB$. Since $\Delta \beta = 10 \log_{10} \left(\frac{I_1}{I_2}\right)$, we have $50 = 10 \log_{10} \left(\frac{I_1}{I_2}\right) \implies 5 = \log_{10} \left(\frac{I_1}{I_2}\right) \implies \frac{I_1}{I_2} = 10^5$.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
