INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('04dec40d-e802-52e9-9c53-d3274a35e4dd', 'd2b54663-8d63-56fa-a512-dca908a85bdd', 17, '<p>A ball is projected upwards at an angle of $60^{\circ}$ with the horizontal. If the initial kinetic energy of projection is $K$ what will be the kinetic energy of the ball at its maximum height? (Neglect air resistance)</p>', '<p>A ball is projected upwards at an angle of $60^{\circ}$ with the horizontal. If the initial kinetic energy of projection is $K$ what will be the kinetic energy of the ball at its maximum height? (Neglect air resistance)</p>', NULL, 'Initial kinetic energy is $K = \frac{1}{2}mv^2$. At the maximum height, the vertical velocity is zero, and the horizontal velocity is constant at $v_x = v \cos 60^{\circ} = \frac{v}{2}$. The kinetic energy at the top is $K_{top} = \frac{1}{2}m(v/2)^2 = \frac{1}{4}(\frac{1}{2}mv^2) = \frac{K}{4}$.', 'Initial kinetic energy is $K = \frac{1}{2}mv^2$. At the maximum height, the vertical velocity is zero, and the horizontal velocity is constant at $v_x = v \cos 60^{\circ} = \frac{v}{2}$. The kinetic energy at the top is $K_{top} = \frac{1}{2}m(v/2)^2 = \frac{1}{4}(\frac{1}{2}mv^2) = \frac{K}{4}$.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
