INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('6cbe2e17-40c1-571b-b22f-4fea8c99517b', 'd2b54663-8d63-56fa-a512-dca908a85bdd', 20, '<p>The variation of linear magnification ($m$) of real images formed by a convex lens with the image distance ($v$) is best represented by</p>', '<p>The variation of linear magnification ($m$) of real images formed by a convex lens with the image distance ($v$) is best represented by</p>', NULL, 'Using the lens formula $\frac{1}{v} - \frac{1}{u} = \frac{1}{f}$. Multiply by $v$: $1 - \frac{v}{u} = \frac{v}{f}$. Magnification is $m = \frac{v}{u}$ (using absolute distances for real images makes it mathematically equivalent to $1 + m = \frac{v}{f}$ strictly based on sign convention, giving $m = \frac{v}{f} - 1$). This denotes a straight line with a positive slope ($\frac{1}{f}$) and a negative y-intercept ($-1$).', 'Using the lens formula $\frac{1}{v} - \frac{1}{u} = \frac{1}{f}$. Multiply by $v$: $1 - \frac{v}{u} = \frac{v}{f}$. Magnification is $m = \frac{v}{u}$ (using absolute distances for real images makes it mathematically equivalent to $1 + m = \frac{v}{f}$ strictly based on sign convention, giving $m = \frac{v}{f} - 1$). This denotes a straight line with a positive slope ($\frac{1}{f}$) and a negative y-intercept ($-1$).', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
