INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('110f9eb3-9d7a-56c7-a194-8b0f76a89c75', 'd2b54663-8d63-56fa-a512-dca908a85bdd', 21, '<p>A thin light circular loop of radius $2\ cm$ is kept just below the surface of a liquid. If a force of $0.04\ N$ is required to pull this loop out from the surface of the liquid (just before the liquid film breaks), what is the surface tension of the liquid?</p>', '<p>A thin light circular loop of radius $2\ cm$ is kept just below the surface of a liquid. If a force of $0.04\ N$ is required to pull this loop out from the surface of the liquid (just before the liquid film breaks), what is the surface tension of the liquid?</p>', NULL, 'When a thin circular loop is pulled from a liquid, the surface tension acts on both the inner and the outer circumference of the loop.<br>The total length of the surface film in contact with the loop is $L = 2 \times (2\pi r) = 4\pi r$.<br>The force required to overcome surface tension is $F = T \times L$, where $T$ is the surface tension.<br>Given $F = 0.04\ N$ and $r = 2\ cm = 0.02\ m$.<br>$0.04 = T \times 4\pi(0.02) \implies 0.04 = T \times 0.08\pi$<br>$T = \frac{0.04}{0.08\pi} = \frac{1}{2\pi}\ N\ m^{-1}$.', 'When a thin circular loop is pulled from a liquid, the surface tension acts on both the inner and the outer circumference of the loop.<br>The total length of the surface film in contact with the loop is $L = 2 \times (2\pi r) = 4\pi r$.<br>The force required to overcome surface tension is $F = T \times L$, where $T$ is the surface tension.<br>Given $F = 0.04\ N$ and $r = 2\ cm = 0.02\ m$.<br>$0.04 = T \times 4\pi(0.02) \implies 0.04 = T \times 0.08\pi$<br>$T = \frac{0.04}{0.08\pi} = \frac{1}{2\pi}\ N\ m^{-1}$.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
