INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('30ee64c7-cbfc-532f-a7be-57f8d1dc00a0', 'd2b54663-8d63-56fa-a512-dca908a85bdd', 22, '<p>In a uniformly charged hollow metallic spherical shell, the variation of the electric potential ($V$) with distance ($r$) from center is best represented by,</p>', '<p>In a uniformly charged hollow metallic spherical shell, the variation of the electric potential ($V$) with distance ($r$) from center is best represented by,</p>', NULL, 'Inside a uniformly charged hollow metallic spherical shell, the electric field is zero. Since $E = -\frac{dV}{dr}$, the electric potential $V$ must be constant inside the shell and equal to the potential at its surface ($V = \frac{Q}{4\pi\epsilon_0 R}$ for $r \le R$).<br>Outside the shell, it behaves like a point charge, and the potential decreases inversely with distance ($V \propto \frac{1}{r}$ for $r > R$).<br>Graph 2 correctly shows a horizontal straight line for the inside region and an inverse curve for the outside region.', 'Inside a uniformly charged hollow metallic spherical shell, the electric field is zero. Since $E = -\frac{dV}{dr}$, the electric potential $V$ must be constant inside the shell and equal to the potential at its surface ($V = \frac{Q}{4\pi\epsilon_0 R}$ for $r \le R$).<br>Outside the shell, it behaves like a point charge, and the potential decreases inversely with distance ($V \propto \frac{1}{r}$ for $r > R$).<br>Graph 2 correctly shows a horizontal straight line for the inside region and an inverse curve for the outside region.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
