INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('6e49cee0-4da5-5ddb-9a1b-062525c8b611', 'd2b54663-8d63-56fa-a512-dca908a85bdd', 34, '<p>A set of parallel resistors and a set of series resistors are connected as shown in the figure. The resistance values of resistors may or may not be the same. Which of the following statements is always true?</p>', '<p>A set of parallel resistors and a set of series resistors are connected as shown in the figure. The resistance values of resistors may or may not be the same. Which of the following statements is always true?</p>', NULL, 'Let the equivalent resistance of the parallel group be $R_p$ and the series group be $R_{s1}, R_{s2}, R_{s3}$. If the two sets are in series with each other, the total equivalent resistance is $R_{eq} = R_p + R_{s1} + R_{s2} + \dots$<br>Since $R_p > 0$, the total resistance $R_{eq}$ is strictly greater than any individual series resistor ($R_{s1}$, $R_{s2}$, etc.). This holds true regardless of the specific resistance values.', 'Let the equivalent resistance of the parallel group be $R_p$ and the series group be $R_{s1}, R_{s2}, R_{s3}$. If the two sets are in series with each other, the total equivalent resistance is $R_{eq} = R_p + R_{s1} + R_{s2} + \dots$<br>Since $R_p > 0$, the total resistance $R_{eq}$ is strictly greater than any individual series resistor ($R_{s1}$, $R_{s2}$, etc.). This holds true regardless of the specific resistance values.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('091c6afb-9a8e-4f4a-af72-cb0c30e43ad4', '6e49cee0-4da5-5ddb-9a1b-062525c8b611', 'The current through each resistor in the set of parallel resistors is the same.', 'The current through each resistor in the set of parallel resistors is the same.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('d2fef031-0311-4b55-a6e0-e39b1228b6e2', '6e49cee0-4da5-5ddb-9a1b-062525c8b611', 'The voltage drop across each resistor in the set of series resistors is the same.', 'The voltage drop across each resistor in the set of series resistors is the same.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('5afed51e-8879-49fd-a436-a12d1ebd7cab', '6e49cee0-4da5-5ddb-9a1b-062525c8b611', 'The total resistance of the entire network is greater than the resistance of any individual resistor in the set of series resistors.', 'The total resistance of the entire network is greater than the resistance of any individual resistor in the set of series resistors.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('01cbe0d9-d625-4b53-a18b-11224e6f075d', '6e49cee0-4da5-5ddb-9a1b-062525c8b611', 'The total resistance of the entire network is less than the largest resistance in the set of parallel resistors.', 'The total resistance of the entire network is less than the largest resistance in the set of parallel resistors.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('10027d5b-913c-483b-b8f4-9fb7b24ef4e4', '6e49cee0-4da5-5ddb-9a1b-062525c8b611', 'The total resistance of the entire network is less than the resistance of any individual resistor in the network.', 'The total resistance of the entire network is less than the resistance of any individual resistor in the network.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('b1699e58-12d7-54b7-9a43-347b11740c45', 'd2b54663-8d63-56fa-a512-dca908a85bdd', 35, '<p>One electron is moving opposite to a uniform electric field ($E$) and another electron is moving perpendicular to a uniform magnetic field ($B$) as shown in figures (1) and (2). For each situation the de Broglie wavelength of the electrons respectively</p>', '<p>One electron is moving opposite to a uniform electric field ($E$) and another electron is moving perpendicular to a uniform magnetic field ($B$) as shown in figures (1) and (2). For each situation the de Broglie wavelength of the electrons respectively</p>', NULL, 'The de Broglie wavelength is given by $\lambda = \frac{h}{p} = \frac{h}{mv}$.<br>In Figure (1), the electron moves opposite to the electric field. The electric force on a negative charge is opposite to the field direction, so the force is in the direction of motion. The electron accelerates, its velocity ($v$) increases, so its wavelength $\lambda$ decreases.<br>In Figure (2), the magnetic force on the moving electron is always perpendicular to its velocity. This force changes the direction of the electron (causing circular motion) but does not do any work, so its speed ($v$) and momentum magnitude ($p$) remain constant. Therefore, its wavelength $\lambda$ does not change.', 'The de Broglie wavelength is given by $\lambda = \frac{h}{p} = \frac{h}{mv}$.<br>In Figure (1), the electron moves opposite to the electric field. The electric force on a negative charge is opposite to the field direction, so the force is in the direction of motion. The electron accelerates, its velocity ($v$) increases, so its wavelength $\lambda$ decreases.<br>In Figure (2), the magnetic force on the moving electron is always perpendicular to its velocity. This force changes the direction of the electron (causing circular motion) but does not do any work, so its speed ($v$) and momentum magnitude ($p$) remain constant. Therefore, its wavelength $\lambda$ does not change.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
