INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('782bc034-d79b-5de4-b7df-75c012f8bd9b', 'd2b54663-8d63-56fa-a512-dca908a85bdd', 38, '<p>A water tank having a large cross-sectional area is kept on a support of height $h$. From a small hole close to the bottom of the tank ejects a horizontal stream of water. Water strikes the ground at a horizontal distance $d$ from an edge of the tank as shown in the figure. What is the height ($y$) of water in the tank?</p>', '<p>A water tank having a large cross-sectional area is kept on a support of height $h$. From a small hole close to the bottom of the tank ejects a horizontal stream of water. Water strikes the ground at a horizontal distance $d$ from an edge of the tank as shown in the figure. What is the height ($y$) of water in the tank?</p>', NULL, 'According to Torricelli''s Law, the velocity of the water leaving the hole is $v = \sqrt{2gy}$.<br>The time $t$ it takes for the water to fall a vertical distance $h$ to the ground is found using $h = \frac{1}{2}gt^2$, which gives $t = \sqrt{\frac{2h}{g}}$.<br>The horizontal distance $d$ is given by $d = v \times t = \sqrt{2gy} \times \sqrt{\frac{2h}{g}} = \sqrt{4yh} = 2\sqrt{yh}$.<br>Squaring both sides gives $d^2 = 4yh$.<br>Rearranging to solve for $y$ yields $y = \frac{d^2}{4h}$.', 'According to Torricelli''s Law, the velocity of the water leaving the hole is $v = \sqrt{2gy}$.<br>The time $t$ it takes for the water to fall a vertical distance $h$ to the ground is found using $h = \frac{1}{2}gt^2$, which gives $t = \sqrt{\frac{2h}{g}}$.<br>The horizontal distance $d$ is given by $d = v \times t = \sqrt{2gy} \times \sqrt{\frac{2h}{g}} = \sqrt{4yh} = 2\sqrt{yh}$.<br>Squaring both sides gives $d^2 = 4yh$.<br>Rearranging to solve for $y$ yields $y = \frac{d^2}{4h}$.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
