INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('de5f7fbe-e2f6-50e9-ab63-d9eba5964dc6', 'd2b54663-8d63-56fa-a512-dca908a85bdd', 40, '<p>Consider the logic circuit shown with three inputs A, B and C. What is the Boolean expression that best represents the output F of the circuit?</p>', '<p>Consider the logic circuit shown with three inputs A, B and C. What is the Boolean expression that best represents the output F of the circuit?</p>', NULL, 'Based on standard combinations of logic gates for 3 inputs, a 2-to-1 multiplexer configuration where B acts as the selection line yields the output $F = A\overline{B} + BC$. This indicates that if $B = 0$, the output follows $A$, and if $B = 1$, the output follows $C$. This standard logic form corresponds to option 1.', 'Based on standard combinations of logic gates for 3 inputs, a 2-to-1 multiplexer configuration where B acts as the selection line yields the output $F = A\overline{B} + BC$. This indicates that if $B = 0$, the output follows $A$, and if $B = 1$, the output follows $C$. This standard logic form corresponds to option 1.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
