INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('dd6e6ded-7e12-41e8-be5a-a27950e18d91', '702f8a88-5a54-5bce-acbb-bf71843377ad', '$\frac{\mu_0 Ii}{2\pi}\frac{ab}{r(r+a)}$', '$\frac{\mu_0 Ii}{2\pi}\frac{ab}{r(r+a)}$', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('52e1adae-5b1f-4964-a686-af6620aabc06', '702f8a88-5a54-5bce-acbb-bf71843377ad', '$\frac{\mu_0 Ii}{2\pi}\frac{(r+a)}{r}$', '$\frac{\mu_0 Ii}{2\pi}\frac{(r+a)}{r}$', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('1ce77f06-3a2e-57f8-89b3-0328ac9ec6cd', 'd2b54663-8d63-56fa-a512-dca908a85bdd', 46, '<p>The $P-V$ diagram shown in the figure illustrates a certain thermodynamic cycle abca of an ideal gas. If the temperature of the gas at point a is $327^\circ C$ what is the temperature of the gas at point c?</p>', '<p>The $P-V$ diagram shown in the figure illustrates a certain thermodynamic cycle abca of an ideal gas. If the temperature of the gas at point a is $327^\circ C$ what is the temperature of the gas at point c?</p>', NULL, 'First, convert the temperature at point a to Kelvin: $T_a = 327 + 273 = 600\ K$.<br>From the graph, the coordinates for point a are $P_a = 6 \times 10^5\ Pa$ and $V_a = 8 \times 10^{-3}\ m^3$.<br>For an ideal gas, $\frac{P_a V_a}{T_a} = \frac{P_c V_c}{T_c}$.<br>The coordinates for point c are $P_c = 4 \times 10^5\ Pa$ and $V_c = 9 \times 10^{-3}\ m^3$.<br>$\frac{6 \times 8}{600} = \frac{4 \times 9}{T_c} \implies \frac{48}{600} = \frac{36}{T_c} \implies 0.08 = \frac{36}{T_c}$.<br>$T_c = \frac{36}{0.08} = 450\ K$.<br>Converting back to Celsius: $T_c = 450 - 273 = 177^\circ C$.', 'First, convert the temperature at point a to Kelvin: $T_a = 327 + 273 = 600\ K$.<br>From the graph, the coordinates for point a are $P_a = 6 \times 10^5\ Pa$ and $V_a = 8 \times 10^{-3}\ m^3$.<br>For an ideal gas, $\frac{P_a V_a}{T_a} = \frac{P_c V_c}{T_c}$.<br>The coordinates for point c are $P_c = 4 \times 10^5\ Pa$ and $V_c = 9 \times 10^{-3}\ m^3$.<br>$\frac{6 \times 8}{600} = \frac{4 \times 9}{T_c} \implies \frac{48}{600} = \frac{36}{T_c} \implies 0.08 = \frac{36}{T_c}$.<br>$T_c = \frac{36}{0.08} = 450\ K$.<br>Converting back to Celsius: $T_c = 450 - 273 = 177^\circ C$.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
