INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('e324f49f-7feb-5872-8883-6864a5a459bd', 'd4b269ea-f747-58e0-ae29-6a0ca5182182', 6, '<p>ද්විමය $1000110_2$ ට තුල්‍ය අෂ්ටක සංඛ්‍යාව කුමක්ද?</p>', '<p>ද්විමය $1000110_2$ ට තුල්‍ය අෂ්ටක සංඛ්‍යාව කුමක්ද?</p>', NULL, 'ද්විමය සංඛ්‍යාව දකුණු පස සිට බිටු 3 බැගින් කාණ්ඩ කළ විට: $001 \quad 000 \quad 110$ ලැබේ.<br>මෙම කාණ්ඩවල අෂ්ටක අගයන්: $001 = 1$, $000 = 0$, $110 = 6$ වේ. එබැවින් පිළිතුර $106_8$ වේ.', 'ද්විමය සංඛ්‍යාව දකුණු පස සිට බිටු 3 බැගින් කාණ්ඩ කළ විට: $001 \quad 000 \quad 110$ ලැබේ.<br>මෙම කාණ්ඩවල අෂ්ටක අගයන්: $001 = 1$, $000 = 0$, $110 = 6$ වේ. එබැවින් පිළිතුර $106_8$ වේ.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
