INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('7e3e192b-f2e3-5265-8599-da068a5afa5b', 'd4b269ea-f747-58e0-ae29-6a0ca5182182', 7, '<p>ද්විමය $10000100_2$ ට තුල්‍ය දශමය සංඛ්‍යාව කුමක්ද?</p>', '<p>ද්විමය $10000100_2$ ට තුල්‍ය දශමය සංඛ්‍යාව කුමක්ද?</p>', NULL, 'ද්විමය අගය දශමයට හැරවීම:<br>$(1 \times 128) + (0 \times 64) + (0 \times 32) + (0 \times 16) + (0 \times 8) + (1 \times 4) + (0 \times 2) + (0 \times 1)$<br>$= 128 + 4 = 132_{10}$.', 'ද්විමය අගය දශමයට හැරවීම:<br>$(1 \times 128) + (0 \times 64) + (0 \times 32) + (0 \times 16) + (0 \times 8) + (1 \times 4) + (0 \times 2) + (0 \times 1)$<br>$= 128 + 4 = 132_{10}$.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
