INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('802950ff-dd92-41f1-9ade-c17a7fdb35f2', '267cfdce-dc9f-51a4-9df6-7e7b74454636', 'පරිශීලකයාට පිළිගැනීම් පණිවුඩයක් (welcome message) පෙන්වා දැක්වීමට', 'පරිශීලකයාට පිළිගැනීම් පණිවුඩයක් (welcome message) පෙන්වා දැක්වීමට', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('62b520f5-14b6-4f64-a51b-95677e29a822', '267cfdce-dc9f-51a4-9df6-7e7b74454636', 'පළමු ඉරට්ටේ සංඛ්‍යා 20 මුද්‍රණය කිරීමට', 'පළමු ඉරට්ටේ සංඛ්‍යා 20 මුද්‍රණය කිරීමට', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('06f9645f-d291-5508-97d6-991b77fbd1c6', 'd4b269ea-f747-58e0-ae29-6a0ca5182182', 23, '<p>පහත දැක්වෙන P, Q සහ R තාර්කික ප්‍රකාශ සලකන්න.<br>$P: (A>=-3)$ AND $(B<25)$<br>$Q: (A<10)$ AND $(B=20)$<br>$R: NOT (A>0)$ OR $(B<15)$<br><br>ඉහත A සහ B අගයන් පිළිවෙළින් -3 සහ 18 වේ නම්, P, Q හා R ප්‍රකාශවල ප්‍රතිඵල පිළිවෙළින් දැක්වෙන්නේ පහත සඳහන් කවරකින්ද?</p>', '<p>පහත දැක්වෙන P, Q සහ R තාර්කික ප්‍රකාශ සලකන්න.<br>$P: (A>=-3)$ AND $(B<25)$<br>$Q: (A<10)$ AND $(B=20)$<br>$R: NOT (A>0)$ OR $(B<15)$<br><br>ඉහත A සහ B අගයන් පිළිවෙළින් -3 සහ 18 වේ නම්, P, Q හා R ප්‍රකාශවල ප්‍රතිඵල පිළිවෙළින් දැක්වෙන්නේ පහත සඳහන් කවරකින්ද?</p>', NULL, 'P: $(-3 \ge -3)$ සත්‍යයි, $(18 < 25)$ සත්‍යයි $\rightarrow$ P සත්‍ය වේ.<br>Q: $(-3 < 10)$ සත්‍යයි, $(18 = 20)$ අසත්‍යයි $\rightarrow$ Q අසත්‍ය වේ.<br>R: $(-3 > 0)$ අසත්‍යයි. එහි NOT අගය සත්‍ය වේ. $(18 < 15)$ අසත්‍ය වුවද, OR යෙදී ඇති බැවින් R සත්‍ය වේ.', 'P: $(-3 \ge -3)$ සත්‍යයි, $(18 < 25)$ සත්‍යයි $\rightarrow$ P සත්‍ය වේ.<br>Q: $(-3 < 10)$ සත්‍යයි, $(18 = 20)$ අසත්‍යයි $\rightarrow$ Q අසත්‍ය වේ.<br>R: $(-3 > 0)$ අසත්‍යයි. එහි NOT අගය සත්‍ය වේ. $(18 < 15)$ අසත්‍ය වුවද, OR යෙදී ඇති බැවින් R සත්‍ය වේ.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
