INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('e4973a33-3ca4-5e2c-9c8a-5317508c8fc4', 'd4b269ea-f747-58e0-ae29-6a0ca5182182', 30, '<p>වෙබ් අඩවියක් ගොඩනැගීමේ ව්‍යාපෘතියකට අදාළව වැරදි ගැළපීමක් දක්වන්නේ පහත කවරක ද?</p>', '<p>වෙබ් අඩවියක් ගොඩනැගීමේ ව්‍යාපෘතියකට අදාළව වැරදි ගැළපීමක් දක්වන්නේ පහත කවරක ද?</p>', NULL, 'ඍජු (Direct), සමාන්තර (Parallel) සහ අදියරමය (Phased) යනු පද්ධතියක් පිහිටුවීමේ (Deployment) ක්‍රමවේදයන් වේ. ඒවා පද්ධති පරීක්ෂා කිරීමේ (Testing) ක්‍රම නොවේ. එබැවින් 4 වන විකල්පය වැරදි ගැළපීමකි.', 'ඍජු (Direct), සමාන්තර (Parallel) සහ අදියරමය (Phased) යනු පද්ධතියක් පිහිටුවීමේ (Deployment) ක්‍රමවේදයන් වේ. ඒවා පද්ධති පරීක්ෂා කිරීමේ (Testing) ක්‍රම නොවේ. එබැවින් 4 වන විකල්පය වැරදි ගැළපීමකි.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('5b0d99b4-5b6c-42bd-886e-3a1cf8dcaec6', 'e4973a33-3ca4-5e2c-9c8a-5317508c8fc4', 'අවශ්‍යතා විශ්ලේෂණය -> සම්මුඛ සාකච්ඡා, මූලාකෘති (prototypes)', 'අවශ්‍යතා විශ්ලේෂණය -> සම්මුඛ සාකච්ඡා, මූලාකෘති (prototypes)', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('b1ee87d3-6dce-41cd-b5b9-718175740b7d', 'e4973a33-3ca4-5e2c-9c8a-5317508c8fc4', 'විසඳුම සැලසුම් කිරීම -> දෘඪාංග හඳුනා ගැනීම, මෘදුකාංග හඳුනා ගැනීම', 'විසඳුම සැලසුම් කිරීම -> දෘඪාංග හඳුනා ගැනීම, මෘදුකාංග හඳුනා ගැනීම', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('f102b3df-691a-46ed-8e3e-31b080863cd4', 'e4973a33-3ca4-5e2c-9c8a-5317508c8fc4', 'කේතනය කිරීම -> HTML, PHP, MySQL', 'කේතනය කිරීම -> HTML, PHP, MySQL', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('ecf9ff6e-645b-4333-829b-fb9140ea71fe', 'e4973a33-3ca4-5e2c-9c8a-5317508c8fc4', 'පරීක්ෂා කිරීම -> ඍජු, සමාන්තර, අදියරමය', 'පරීක්ෂා කිරීම -> ඍජු, සමාන්තර, අදියරමය', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('d1f3e6a3-3f3a-5d3d-aed7-b4bbb24f2d82', 'd4b269ea-f747-58e0-ae29-6a0ca5182182', 31, '<p>ඒකාකාර සම්පත් නිශ්චායකය (URL) සම්බන්ධයෙන් පහත කවර වගන්තියක් නිවැරදි වේද?</p>', '<p>ඒකාකාර සම්පත් නිශ්චායකය (URL) සම්බන්ධයෙන් පහත කවර වගන්තියක් නිවැරදි වේද?</p>', NULL, 'URL (Uniform Resource Locator) යනු අන්තර්ජාලයේ හෝ ලෝක විසිරි වියමනේ ඇති වෙබ් පිටුවක, රූපයක හෝ වෙනත් ගොනුවක අද්විතීය ලිපිනයයි (යොමුවයි).', 'URL (Uniform Resource Locator) යනු අන්තර්ජාලයේ හෝ ලෝක විසිරි වියමනේ ඇති වෙබ් පිටුවක, රූපයක හෝ වෙනත් ගොනුවක අද්විතීය ලිපිනයයි (යොමුවයි).', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('9aa6a379-afee-406f-a388-ee51fd7510b7', 'd1f3e6a3-3f3a-5d3d-aed7-b4bbb24f2d82', 'URL එකක ෆෝල්ඩර නාම ඇතුළත් විය නොහැක.', 'URL එකක ෆෝල්ඩර නාම ඇතුළත් විය නොහැක.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('8f482f62-2e59-4745-9883-be553230312b', 'd1f3e6a3-3f3a-5d3d-aed7-b4bbb24f2d82', 'URL එකක් සමන්විත වන්නේ නියමාවලියෙන් (protocol) සහ වසම් නාමයෙන් (domain name) පමණි.', 'URL එකක් සමන්විත වන්නේ නියමාවලියෙන් (protocol) සහ වසම් නාමයෙන් (domain name) පමණි.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('40bde066-2ddd-49e5-b773-80151b1a390f', 'd1f3e6a3-3f3a-5d3d-aed7-b4bbb24f2d82', 'URL සහ IP යොමුවක් යන දෙකින්ම එකම දෙය හැඟවේ.', 'URL සහ IP යොමුවක් යන දෙකින්ම එකම දෙය හැඟවේ.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('6641ef30-f9ef-471b-b32e-e53a53308a03', 'd1f3e6a3-3f3a-5d3d-aed7-b4bbb24f2d82', 'විශ්ව විසිරි වියමනෙහි (World Wide Web) සම්පතක යොමුව (address) URL මගින් දැක්වෙයි.', 'විශ්ව විසිරි වියමනෙහි (World Wide Web) සම්පතක යොමුව (address) URL මගින් දැක්වෙයි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('39356afa-71c5-56a3-ba6e-65e95006154e', 'd4b269ea-f747-58e0-ae29-6a0ca5182182', 32, '<p>පහත කවර වගන්තියක් නිවැරදි වේද?</p>', '<p>පහත කවර වගන්තියක් නිවැරදි වේද?</p>', NULL, 'වසම් නාම පද්ධති සේවාදායකයේ (DNS Server) ප්‍රධාන කාර්යය වන්නේ මිනිසුන්ට කියවිය හැකි වසම් නාම, පරිගණකයට තේරුම් ගත හැකි IP ලිපින බවට පරිවර්තනය කිරීමයි. වෙබ් සේවාදායකයේ (Web Server) කාර්යය වන්නේ අදාළ වෙබ් පිටු සහ ගොනු පරිශීලකයාගේ බ්‍රවුසරය වෙත ලබා දීමයි.', 'වසම් නාම පද්ධති සේවාදායකයේ (DNS Server) ප්‍රධාන කාර්යය වන්නේ මිනිසුන්ට කියවිය හැකි වසම් නාම, පරිගණකයට තේරුම් ගත හැකි IP ලිපින බවට පරිවර්තනය කිරීමයි. වෙබ් සේවාදායකයේ (Web Server) කාර්යය වන්නේ අදාළ වෙබ් පිටු සහ ගොනු පරිශීලකයාගේ බ්‍රවුසරය වෙත ලබා දීමයි.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('f212d6f4-188c-48e8-a4fc-d4d0605d8d4c', '39356afa-71c5-56a3-ba6e-65e95006154e', 'DNS සේවාදායකයක් වසම් නාම IP යොමු වලට අනුරූපණය කරන අතර වෙබ් සේවාදායකයක් වෙබ් අඩවි අන්තර්ගත එහි පරිශීලකයන්ට ලබා දේ.', 'DNS සේවාදායකයක් වසම් නාම IP යොමු වලට අනුරූපණය කරන අතර වෙබ් සේවාදායකයක් වෙබ් අඩවි අන්තර්ගත එහි පරිශීලකයන්ට ලබා දේ.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('45bb3392-a558-41ad-a21a-6e9680f332a8', '39356afa-71c5-56a3-ba6e-65e95006154e', 'වෙබ් සේවාදායකයක් සහ DNS සේවාදායකයක් යන දෙකම වෙබ් අඩවි අන්තර්ගත ආචය කර ඒවා පරිශීලකයන්ට පිරිනැමීම සිදු කරයි.', 'වෙබ් සේවාදායකයක් සහ DNS සේවාදායකයක් යන දෙකම වෙබ් අඩවි අන්තර්ගත ආචය කර ඒවා පරිශීලකයන්ට පිරිනැමීම සිදු කරයි.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('3b65d5fe-ba89-4e54-9fcf-a1b914f2cc22', '39356afa-71c5-56a3-ba6e-65e95006154e', 'වෙබ් සේවාදායකය සහ DNS සේවාදායකය යන දෙකම HTTP නියමාවලිය භාවිත කරයි.', 'වෙබ් සේවාදායකය සහ DNS සේවාදායකය යන දෙකම HTTP නියමාවලිය භාවිත කරයි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('abb34f69-788c-4fcd-bf1a-ca63e39889df', '39356afa-71c5-56a3-ba6e-65e95006154e', 'වෙබ් සේවාදායකයක් වසම් නාම IP යොමු වලට පරිවර්තනය කරන අතර, DNS සේවාදායකයක් වෙබ් අඩවි අන්තර්ගත සත්කාර කිරීම (hosting) සිදු කරයි.', 'වෙබ් සේවාදායකයක් වසම් නාම IP යොමු වලට පරිවර්තනය කරන අතර, DNS සේවාදායකයක් වෙබ් අඩවි අන්තර්ගත සත්කාර කිරීම (hosting) සිදු කරයි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('4dd06185-4f8c-53c8-828b-8614fda0f42a', 'd4b269ea-f747-58e0-ae29-6a0ca5182182', 33, '<p>දී ඇති ගොනු වර්ග සහ නිදර්ශනාත්මක ගොනු දිගුවල නිවැරදි ගැළපීම ඇත්තේ පහත කවරකද?</p>', '<p>දී ඇති ගොනු වර්ග සහ නිදර්ශනාත්මක ගොනු දිගුවල නිවැරදි ගැළපීම ඇත්තේ පහත කවරකද?</p>', NULL, '.ods සහ .xlsx යනු පැතුරුම්පත් (Spreadsheets) සඳහා භාවිත වන ගොනු දිගු වේ. .mp3 සහ .wav යනු ශ්‍රව්‍ය (Audio) ගොනු වේ. .avi සහ .mp4 යනු දෘශ්‍ය (Video) ගොනු වේ.', '.ods සහ .xlsx යනු පැතුරුම්පත් (Spreadsheets) සඳහා භාවිත වන ගොනු දිගු වේ. .mp3 සහ .wav යනු ශ්‍රව්‍ය (Audio) ගොනු වේ. .avi සහ .mp4 යනු දෘශ්‍ය (Video) ගොනු වේ.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
