INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('2194ed55-378a-40c3-8278-47135b3c8a16', 'f20efe0f-273d-5b0e-80ae-559be0f7fdbb', 'වෙක්ටර් චිත්‍රකයක් විශාල කළ විට එහි තත්වය (quality) බාල වේ.', 'වෙක්ටර් චිත්‍රකයක් විශාල කළ විට එහි තත්වය (quality) බාල වේ.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('eef3fdfb-a700-4cea-9e4e-5c808f6151d4', 'f20efe0f-273d-5b0e-80ae-559be0f7fdbb', 'නිතර විශාලත්වය වෙනස් කිරීම අවශ්‍ය වන ආයතන ලාංඡන වැනි චිත්‍රක සඳහා රාස්ටර් චිත්‍රක සුදුසු නොවේ.', 'නිතර විශාලත්වය වෙනස් කිරීම අවශ්‍ය වන ආයතන ලාංඡන වැනි චිත්‍රක සඳහා රාස්ටර් චිත්‍රක සුදුසු නොවේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('a6e428f8-6667-5d66-b963-cc32c18c0a3f', 'd4b269ea-f747-58e0-ae29-6a0ca5182182', 36, '<p>ගීතයක ශ්‍රව්‍ය ගොනුවක, එම ගීතයට කලින් සහ පසුව ඇති දිගු නිහඬ (silent) කොටස් ඉවත් කිරීම Audacity භාවිතයෙන් කළ යුතුව ඇත. Audacity තුළින් ගොනුව විවෘත කළ පසු, නිහඬ කොටස් ඉවත් කිරීම පහත කවරක් මගින් සිදු කළ හැකිද?</p>
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('1ecbc8a2-67be-4c22-836d-33a46255fc08', 'a6e428f8-6667-5d66-b963-cc32c18c0a3f', 'තේරීමේ මෙවලම (Selection tool) ක්ලික් කරන්න -> වාදනය (Play) ක්ලික් කරන්න', 'තේරීමේ මෙවලම (Selection tool) ක්ලික් කරන්න -> වාදනය (Play) ක්ලික් කරන්න', NULL, 'sanitized', 'v1', 0, 1);
