INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('6e75f28c-7d4a-4af1-8fe7-8a03ff439dae', '6487be35-1961-5955-9be1-b3b6f989906c', 'A, B සහ C සියල්ල ම', 'A, B සහ C සියල්ල ම', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('1b6e77db-37a2-5ffc-900b-a270307514bc', 'd4d43f9b-84e9-5ebf-adcd-485f7cce0433', 1, '<p>ඒකකයක් ඇති නමුත් මානයක් නොමැති පහත සඳහන් භෞතික රාශිය කුමක්ද?</p>', '<p>ඒකකයක් ඇති නමුත් මානයක් නොමැති පහත සඳහන් භෞතික රාශිය කුමක්ද?</p>', NULL, 'ධ්වනි තීව්‍රතා මට්ටම (Sound Intensity Level) මනිනු ලබන්නේ ඩෙසිබෙල් (dB) වලිනි. එය අනුපාතයක් මත පදනම් වූ ලඝුගණක අගයක් වන බැවින් එයට මාන නොමැත, නමුත් ඩෙසිබෙල් යන ඒකකය භාවිත කෙරේ. සමතල කෝණය ද (රේඩියන) මෙවැනිම ඒකකයක් සහිත එහෙත් මාන රහිත රාශියකි.', 'ධ්වනි තීව්‍රතා මට්ටම (Sound Intensity Level) මනිනු ලබන්නේ ඩෙසිබෙල් (dB) වලිනි. එය අනුපාතයක් මත පදනම් වූ ලඝුගණක අගයක් වන බැවින් එයට මාන නොමැත, නමුත් ඩෙසිබෙල් යන ඒකකය භාවිත කෙරේ. සමතල කෝණය ද (රේඩියන) මෙවැනිම ඒකකයක් සහිත එහෙත් මාන රහිත රාශියකි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
