INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('9b3f56ba-7cf5-5d28-b692-9b70097c865c', 'd4d43f9b-84e9-5ebf-adcd-485f7cce0433', 12, '<p>අරය <span class="mhw-eq"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>2</mn><mi>r</mi></mrow><annotation encoding="application/x-tex">2r</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">2</span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span></span></span></span></span> වූ සමජාතීය ඒකාකාර වෘත්තාකාර තහඩුවකින් අරය <span class="mhw-eq"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>r</mi></mrow><annotation encoding="application/x-tex">r</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span></span></span></span></span> වූ වෘත්තාකාර කොටසක් රූපයේ දැක්වෙන පරිදි ඉවත් කරනු ලැබේ. තහඩුවේ ඉතිරි කොටසේ ගුරුත්ව කේන්ද්‍රය පිහිටීමට වඩාත්ම ඉඩ ඇති ලක්ෂ්‍යය වනුයේ කුමක්ද?</p>
