INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('feea571b-887a-4001-92c1-e3844599c744', '53c47b9f-a1e4-57b5-93c1-daf997616871', 'C කම්බිය ට විශාලතම විතතිය ඇත.', 'C කම්බිය ට විශාලතම විතතිය ඇත.', NULL, 'sanitized', 'v1', 2, 0);
