INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('6ca6e3b7-26eb-5264-a14b-7f5f32090c3f', 'd4d43f9b-84e9-5ebf-adcd-485f7cce0433', 33, '<p><span class="mhw-eq"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mn>30</mn><mo lspace="0em" rspace="0em">∘</mo></msup><mtext>C</mtext></mrow><annotation encoding="application/x-tex">30^{\circ}\text{C}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">3</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6741em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">∘</span></span></span></span></span></span></span></span></span><span class="mord text"><span class="mord">C</span></span></span></span></span></span> හි පවතින ජලය <span class="mhw-eq"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>100</mn><mtext> g</mtext></mrow><annotation encoding="application/x-tex">100\text{ g}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8389em;vertical-align:-0.1944em;"></span><span class="mord">100</span><span class="mord text"><span class="mord"> g</span></span></span></span></span></span> ක ස්කන්ධයක් සහ <span class="mhw-eq"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo>−</mo><msup><mn>10</mn><mo lspace="0em" rspace="0em">∘</mo></msup><mtext>C</mtext></mrow><annotation encoding="application/x-tex">-10^{\circ}\text{C}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7667em;vertical-align:-0.0833em;"></span><span class="mord">−</span><span class="mord">1</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6741em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">∘</span></span></span></span></span></span></span></span></span><span class="mord text"><span class="mord">C</span></span></span></span></span></span> පවතින අයිස් <span class="mhw-eq"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>100</mn><mtext> g</mtext></mrow><annotation encoding="application/x-tex">100\text{ g}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8389em;vertical-align:-0.1944em;"></span><span class="mord">100</span><span class="mord text"><span class="mord"> g</span></span></span></span></span></span> ක ස්කන්ධයක් පරිවරණය කරන ලද භාජනයක, පරිසරය සමග තාප හුවමාරුවක් නොවන පරිදි මිශ්‍ර කරන ලදී. අයිස් සහ ජලයේ විශිෂ්ට තාප ධාරිතා පිළිවෙළින් <span class="mhw-eq"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>2</mn><mo>×</mo><msup><mn>10</mn><mn>3</mn></msup><msup><mtext> J kg</mtext><mrow><mo>−</mo><mn>1</mn></mrow></msup><msup><mtext> K</mtext><mrow><mo>−</mo><mn>1</mn></mrow></msup></mrow><annotation encoding="application/x-tex">2\times 10^3\text{ J kg}^{-1}\text{ K}^{-1}</annotation></s