INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('11004d05-7b6a-47b0-91c0-6ba4317a23f3', '0156e9ac-547e-5135-a0ca-bb13761d3eaf', 'ශ්‍රේණිගත ප්‍රතිරෝධක කට්ටලයේ එක් එක් ප්‍රතිරෝධකය හරහා වෝල්ටීයතා බැස්ම එකම වේ.', 'ශ්‍රේණිගත ප්‍රතිරෝධක කට්ටලයේ එක් එක් ප්‍රතිරෝධකය හරහා වෝල්ටීයතා බැස්ම එකම වේ.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('f7af6094-66c5-4e63-893c-23ee3689758c', '0156e9ac-547e-5135-a0ca-bb13761d3eaf', 'ශ්‍රේණිගත ප්‍රතිරෝධක කට්ටලයේ ඕනෑම තනි ප්‍රතිරෝධකයක ප්‍රතිරෝධ අගයට වඩා සමස්ත ජාලයේ මුළු ප්‍රතිරෝධය වැඩි වේ.', 'ශ්‍රේණිගත ප්‍රතිරෝධක කට්ටලයේ ඕනෑම තනි ප්‍රතිරෝධකයක ප්‍රතිරෝධ අගයට වඩා සමස්ත ජාලයේ මුළු ප්‍රතිරෝධය වැඩි වේ.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('5d204e47-9992-41de-b1be-ea2463a54525', '0156e9ac-547e-5135-a0ca-bb13761d3eaf', 'සමස්ත ජාලයේ මුළු ප්‍රතිරෝධය සමාන්තරගත ප්‍රතිරෝධක කට්ටලයේ විශාලතම ප්‍රතිරෝධයට වඩා අඩු ය.', 'සමස්ත ජාලයේ මුළු ප්‍රතිරෝධය සමාන්තරගත ප්‍රතිරෝධක කට්ටලයේ විශාලතම ප්‍රතිරෝධයට වඩා අඩු ය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('c00e6c48-e650-4131-828a-730fca61fa32', '0156e9ac-547e-5135-a0ca-bb13761d3eaf', 'සමස්ත ජාලයේ මුළු ප්‍රතිරෝධය ජාලයේ ඕනෑම තනි ප්‍රතිරෝධකයක ප්‍රතිරෝධයට වඩා අඩු ය.', 'සමස්ත ජාලයේ මුළු ප්‍රතිරෝධය ජාලයේ ඕනෑම තනි ප්‍රතිරෝධකයක ප්‍රතිරෝධයට වඩා අඩු ය.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('db5ce37d-767e-5e64-9e13-fc4d8dcd19d5', 'd4d43f9b-84e9-5ebf-adcd-485f7cce0433', 35, '<p>එක් ඉලෙක්ට්‍රෝනයක් ඒකාකාර විද්‍යුත් ක්ෂේත්‍රයකට (E) ප්‍රතිවිරුද්ධව චලනය වන අතර තවත් ඉලෙක්ට්‍රෝනයක් ඒකාකාර චුම්බක ක්ෂේත්‍රයකට (B) ලම්බකව චලනය වේ. එක් එක් අවස්ථාව සඳහා ඉලෙක්ට්‍රෝනවල ඩි බ්‍රෝග්ලි තරංග ආයාමය පිළිවෙළින්,</p>
