INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('f667c017-1a7e-58dc-bc53-b259c52667fe', 'd4d43f9b-84e9-5ebf-adcd-485f7cce0433', 46, '<p>P-V සටහන මගින් පරිපූර්ණ වායුවක යම් තාපගතික චක්‍රයක් විදහා දක්වයි. a ලක්ෂ්‍යයේදී වායුවේ උෂ්ණත්වය <span class="mhw-eq"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mn>327</mn><mo lspace="0em" rspace="0em">∘</mo></msup><mtext>C</mtext></mrow><annotation encoding="application/x-tex">327^{\\circ}\\text{C}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">32</span><span class="mord"><span class="mord">7</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6741em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">∘</span></span></span></span></span></span></span></span></span><span class="mord text"><span class="mord">C</span></span></span></span></span></span> නම් c ලක්ෂ්‍යයේදී වායුවේ උෂ්ණත්වය කොපමණ ද? (a: <span class="mhw-eq"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>6</mn><mo>×</mo><msup><mn>10</mn><mn>5</mn></msup><mtext> Pa</mtext><mo separator="true">,</mo><mn>8</mn><mo>×</mo><msup><mn>10</mn><mrow><mo>−</mo><mn>3</mn></mrow></msup><msup><mtext> m</mtext><mn>3</mn></msup></mrow><annotation encoding="application/x-tex">6 \\times 10^5\\text{ Pa}, 8 \\times 10^{-3}\\text{ m}^3</annotation></semantics></math></span><span class="kate