INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e74d8d7c-fe2d-4a21-b926-c6f7f48607e3', '059e6797-607b-51fb-8870-bab95c79bb16', '(A), (B) සහ (C) සියල්ලම සත්‍ය වේ.', '(A), (B) සහ (C) සියල්ලම සත්‍ය වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('072698ec-7c62-518b-bbd0-02fdee5b29d5', 'd9ebfb7a-ff17-5183-9b70-9c4d3adf95c3', 8, '<p>ඒකලිත q ලක්ෂ්‍යයීය ආරෝපණයක් පාරවිද්‍යුත් නියතය k වන පාරවිද්‍යුත් මාධ්‍යයක තබා ඇත. ලක්ෂ්‍යයීය ආරෝපණයේ සිට r දුරකින් මාධ්‍යය තුළ ඇති ලක්ෂ්‍යයක විද්‍යුත් ක්ෂේත්‍ර තීව්‍රතාවයේ විශාලත්වය කුමක්ද?</p>', '<p>ඒකලිත q ලක්ෂ්‍යයීය ආරෝපණයක් පාරවිද්‍යුත් නියතය k වන පාරවිද්‍යුත් මාධ්‍යයක තබා ඇත. ලක්ෂ්‍යයීය ආරෝපණයේ සිට r දුරකින් මාධ්‍යය තුළ ඇති ලක්ෂ්‍යයක විද්‍යුත් ක්ෂේත්‍ර තීව්‍රතාවයේ විශාලත්වය කුමක්ද?</p>', NULL, 'ශුන්‍ය අවකාශයකදී විද්‍යුත් ක්ෂේත්‍ර තීව්‍රතාවය $E = \frac{q}{4\pi\epsilon_0 r^2}$ වේ.<br>නමුත් පාරවිද්‍යුත් නියතය $k$ (හෝ සාපේක්ෂ පාරවිද්‍යුත්තාව $\epsilon_r$) වන මාධ්‍යයක් තුළදී සමස්ත පාරවිද්‍යුත්තාව $\epsilon = k\epsilon_0$ වන බැවින්, ක්ෂේත්‍ර තීව්‍රතාවය $E = \frac{q}{4\pi k\epsilon_0 r^2}$ බවට පත් වේ.', 'ශුන්‍ය අවකාශයකදී විද්‍යුත් ක්ෂේත්‍ර තීව්‍රතාවය $E = \frac{q}{4\pi\epsilon_0 r^2}$ වේ.<br>නමුත් පාරවිද්‍යුත් නියතය $k$ (හෝ සාපේක්ෂ පාරවිද්‍යුත්තාව $\epsilon_r$) වන මාධ්‍යයක් තුළදී සමස්ත පාරවිද්‍යුත්තාව $\epsilon = k\epsilon_0$ වන බැවින්, ක්ෂේත්‍ර තීව්‍රතාවය $E = \frac{q}{4\pi k\epsilon_0 r^2}$ බවට පත් වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
