INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('895a45f1-7bda-4bca-8953-bc7fcd46f2d3', '84aa7e9d-b656-5fbb-b80e-7911655b7193', 'අවතල කාචයක්, -0.02 D', 'අවතල කාචයක්, -0.02 D', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('353f1271-8993-57e8-9d71-399c3d25621c', 'd9ebfb7a-ff17-5183-9b70-9c4d3adf95c3', 11, '<p>නොඇදි දිග $10~cm$ ක් වන ඒකාකාර කම්බියකට $1~kg$ ක ස්කන්ධයක් සම්බන්ධ කර ඇත. කම්බියේ හරස්කඩ වර්ගඵලය $1~cm^{2}$ වන අතර කම්බියේ ද්‍රව්‍යයේ යං මාපාංකය $1.0 \\times 10^{11}~N~m^{-2}$ වේ. රූපයේ පෙන්වා ඇති පරිදි අරයේ ආසන්න අගය $10~cm$ වන වෘත්තයක $2~m~s^{-1}$ ක නියත වේගයකින් ස්කන්ධය ගමන් කිරීමට සලස්වන ලදී. කම්බියේ විතතිය කොපමණ ද?</p>
