INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('a43f9ed8-6576-5067-933a-891d3672079c', 'd9ebfb7a-ff17-5183-9b70-9c4d3adf95c3', 18, '<p>සමාන ආරෝපණ ඇති, ස්කන්ධ පිළිවෙළින් $m_{A}$ සහ $m_{B}$ වූ A සහ B අංශු දෙකක් ඒකාකාර චුම්බක ක්ෂේත්‍රයකට ලම්බකව ගමන් කරයි. අංශු වල වේග පිළිවෙළින් $v_{A}$ සහ $v_{B}$ වන අතර ඒවායේ ගමන් පථ රූපයේ දැක්වෙන පරිදි වේ (මෙහි A හි පථයේ අරය B හි පථයේ අරයට වඩා විශාලය). පහත සඳහන් ඒවායින් සත්‍ය වන්නේ කුමක්ද?</p>
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('699201fb-316c-417a-b177-19c625434cb2', 'a43f9ed8-6576-5067-933a-891d3672079c', '$m_{A}v_{A} > m_{B}v_{B}$', '$m_{A}v_{A} > m_{B}v_{B}$', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('9e85b47a-17ef-4ad1-b899-02658e88fdc9', 'a43f9ed8-6576-5067-933a-891d3672079c', '$m_{A}v_{A} < m_{B}v_{B}$', '$m_{A}v_{A} < m_{B}v_{B}$', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('ad8ed3b1-31ac-46dc-add5-6c5ef3ac9908', 'a43f9ed8-6576-5067-933a-891d3672079c', '$m_{A} < m_{B}$ සහ $v_{A} < v_{B}$', '$m_{A} < m_{B}$ සහ $v_{A} < v_{B}$', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('cbae6335-0bb1-40ea-904e-9ff340e46a4a', 'a43f9ed8-6576-5067-933a-891d3672079c', '$m_{A} = m_{B}$ සහ $v_{A} = v_{B}$', '$m_{A} = m_{B}$ සහ $v_{A} = v_{B}$', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('f49cd3d0-8986-402b-ad26-f698934130d4', 'a43f9ed8-6576-5067-933a-891d3672079c', '$m_{A} = m_{B}$ සහ $v_{A} < v_{B}$', '$m_{A} = m_{B}$ සහ $v_{A} < v_{B}$', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('5927a2ac-83b0-5286-923d-cb08f9e0a9bd', 'd9ebfb7a-ff17-5183-9b70-9c4d3adf95c3', 19, '<p>හීලියම් (සාපේක්ෂ පරමාණුක ස්කන්ධය = 4) වායුවෙන් පුරවා එක් කෙළවරක් වසා ඇති නළයක මූලික සංඛ්‍යාතය $f$ වේ. ඉන්පසු එම උෂ්ණත්වයේදීම නළය නියෝන් (සාපේක්ෂ පරමාණුක ස්කන්ධය = 20) වායුවෙන් පුරවනු ලැබේ. වායු දෙකම පරිපූර්ණ නම්, නියෝන් පිර වූ නළයේ මූලික සංඛ්‍යාතය කුමක්ද?</p>', '<p>හීලියම් (සාපේක්ෂ පරමාණුක ස්කන්ධය = 4) වායුවෙන් පුරවා එක් කෙළවරක් වසා ඇති නළයක මූලික සංඛ්‍යාතය $f$ වේ. ඉන්පසු එම උෂ්ණත්වයේදීම නළය නියෝන් (සාපේක්ෂ පරමාණුක ස්කන්ධය = 20) වායුවෙන් පුරවනු ලැබේ. වායු දෙකම පරිපූර්ණ නම්, නියෝන් පිර වූ නළයේ මූලික සංඛ්‍යාතය කුමක්ද?</p>', NULL, 'වසා ඇති නළයක මූලික සංඛ්‍යාතය $f = \frac{v}{4L}$ වේ. වායුවක ධ්වනි ප්‍රවේගය $v = \sqrt{\frac{\gamma RT}{M}}$ වේ.<br>එකම උෂ්ණත්වයේ පවතින ඒක පරමාණුක වායූන් දෙකක් බැවින් $\gamma$, $R$, $T$ සහ $L$ නියත වේ. එබැවින් $f \propto \frac{1}{\sqrt{M}}$ වේ.<br>$\frac{f_{Ne}}{f_{He}} = \sqrt{\frac{M_{He}}{M_{Ne}}} = \sqrt{\frac{4}{20}} = \frac{1}{\sqrt{5}} \implies f_{Ne} = \frac{f}{\sqrt{5}}$ වේ.', 'වසා ඇති නළයක මූලික සංඛ්‍යාතය $f = \frac{v}{4L}$ වේ. වායුවක ධ්වනි ප්‍රවේගය $v = \sqrt{\frac{\gamma RT}{M}}$ වේ.<br>එකම උෂ්ණත්වයේ පවතින ඒක පරමාණුක වායූන් දෙකක් බැවින් $\gamma$, $R$, $T$ සහ $L$ නියත වේ. එබැවින් $f \propto \frac{1}{\sqrt{M}}$ වේ.<br>$\frac{f_{Ne}}{f_{He}} = \sqrt{\frac{M_{He}}{M_{Ne}}} = \sqrt{\frac{4}{20}} = \frac{1}{\sqrt{5}} \implies f_{Ne} = \frac{f}{\sqrt{5}}$ වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
